1	// Loading site/data/ and the questions the page asks of it. Short keys are documented in crossfoot/sitebuild.py.
2	export const fmt = n => (n === null || n === undefined ? '' : Number(n).toLocaleString('en-US'));
3	
4	// the files fetched so far, for the "Loading run…" line
5	export const progress = { n: 0, on: () => {} };
6	export const loaded = () => { progress.n++; progress.on(progress.n); };
7	
8	export async function getJSON(file) {
9	  let r;
10	  try { r = await fetch(file); } catch (e) { throw new LoadError(file); }
11	  if (!r.ok) throw new LoadError(file, r.status === 404);
12	  let d;
13	  try { d = await r.json(); } catch (e) { throw new LoadError(file); }
14	  loaded();
15	  return d;
16	}
17	export class LoadError extends Error { constructor(file, missing = false) { super(file); this.file = file; this.missing = missing; } }
18	export const loadMessage = file => `Couldn't load ${file}. Reload, or open the repository's runs folder.`;
19	
20	// the report layout (one precinct per section, four figures per row): its column keys in print order, and their words
21	export const COLS = ['total', 'absentee', 'early', 'election_day'];
22	export const COL_WORD = { total: 'total', absentee: 'absentee', early: 'early voting', election_day: 'election day' };
23	const TOTAL_ROW = /^(total votes cast|cast votes)$/i;
24	// "Precinct 2A" is already a precinct; "101" is not
25	export const pcl = p => (/^precinct\b/i.test(String(p)) ? String(p) : `precinct ${p}`);
26	
27	export const idOf = v => `${v.p}:${v.b}:${v.r}:${v.c}`;
28	const isTotal = v => v.r === 'col' || v.r === 'row' || v.r === 'grand';
29	
30	export class Store {
31	  constructor(d) {
32	    this.d = d;
33	    this.values = d.values; this.checks = d.checks; this.pages = d.pages;
34	    this.blocks = new Map(d.blocks.map(b => [`${b.p}:${b.id}`, b]));
35	    this.byId = new Map(); this.byPage = new Map();
36	    d.values.forEach((v, i) => {
37	      v.i = i; this.byId.set(idOf(v), i);
38	      if (!this.byPage.has(v.p)) this.byPage.set(v.p, []);
39	      this.byPage.get(v.p).push(i);
40	    });
41	    this.chk = new Map();
42	    d.checks.forEach((c, i) => { c.i = i; this.chk.set(`${c.k}:${c.p}:${c.b}:${c.y}`, c); });
43	    // the audit's findings, when the run has them: by id, by the value they sit on, and by group
44	    this.fd = d.fd || null;
45	    this.items = this.fd ? this.fd.items : [];
46	    this.itemById = new Map(this.items.map(f => [f.id, f]));
47	    this.itemByRef = new Map(this.items.filter(f => f.ref !== undefined).map(f => [f.ref, f]));
48	    this.groupById = new Map((this.fd ? this.fd.groups : []).map(g => [g.id, g]));
49	    // the report layout: the rows' crops, the contest sums by block and column, the contest total rows
50	    this.report = d.layout === 'report';
51	    this.rc = d.rc || [];
52	    this.rcByRow = new Map(this.rc.map(r => [`${r.p}:${r.b}:${r.r}`, r]));
53	    this.contest = new Map(); this.totRow = new Map();
54	    this.fileAt = new Map(this.items.filter(f => f.ref !== undefined).map(f => [f.ref, f.file]));   // the file's value where a finding sits on the value
55	    if (this.report) {
56	      d.checks.forEach(c => { if (c.k === 'report_contest') this.contest.set(`${c.b}:${c.y}`, c); });
57	      d.values.forEach((v, i) => { if (TOTAL_ROW.test(String(v.r).trim())) this.totRow.set(`${v.b}:${v.c}`, i); });
58	    }
59	  }
60	  isTotal(v) { return this.report ? false : isTotal(v); }
61	  rowCrop(v) { return this.report ? this.rcByRow.get(`${v.p}:${v.b}:${v.r}`) || null : null; }
62	  // the four values of the row of a value of the report layout, in column order (undefined where a cell is missing)
63	  rowCells(v) { return COLS.map(c => this.byId.get(`${v.p}:${v.b}:${v.r}:${c}`)); }
64	  block(v) { return this.blocks.get(`${v.p}:${v.b}`); }
65	  // the sums a value sits on: [{check, axis}], axis 'col' (down) or 'row' (across), column first
66	  sumsFor(v) {
67	    if (this.report) {
68	      const out = [];
69	      const k = this.contest.get(`${v.b}:${v.c}`), tot = this.totRow.get(`${v.b}:${v.c}`);
70	      if (k && (k.t.includes(v.i) || tot === v.i)) out.push({ check: k, axis: 'col' });
71	      const r = this.chk.get(`report_row:${v.p}:${v.b}:${v.r}`);
72	      if (r) out.push({ check: r, axis: 'row' });
73	      return out;
74	    }
75	    const g = k => this.chk.get(k);
76	    const out = [];
77	    const add = (c, axis) => { if (c) out.push({ check: c, axis }); };
78	    if (!isTotal(v)) { add(g(`col:${v.p}:${v.b}:${v.c}`), 'col'); add(g(`row:${v.p}:${v.b}:${v.r}`), 'row'); }
79	    else if (v.r === 'col') { add(g(`col:${v.p}:${v.b}:${v.c}`), 'col'); add(g(`grand:${v.p}:${v.b}:`), 'row'); }
80	    else if (v.r === 'row') { add(g(`row:${v.p}:${v.b}:${v.c}`), 'row'); add(g(`grand_row:${v.p}:${v.b}:`), 'col'); }
81	    else { add(g(`grand:${v.p}:${v.b}:`), 'row'); add(g(`grand_row:${v.p}:${v.b}:`), 'col'); }
82	    return out;
83	  }
84	  termsOf(c) { return c.t.map(i => this.values[i]); }
85	  // the printed total a sum is decided by
86	  totalOf(c) {
