88	    if (c.k === 'report_contest') { const i = this.totRow.get(`${c.b}:${c.y}`); return i === undefined ? null : this.values[i]; }
89	    const key = c.k === 'grand' || c.k === 'grand_row' ? `${c.p}:${c.b}:grand:` : `${c.p}:${c.b}:${c.k}:${c.y}`;
90	    const i = this.byId.get(key);
91	    return i === undefined ? null : this.values[i];
92	  }
93	  // where to draw a sum, in image pixels, or null when the scan gave no boxes for it
94	  band(c) {
95	    if (c.k === 'report_row' || c.k === 'report_contest') return this.reportBand(c);
96	    const terms = this.termsOf(c).filter(t => t.x), total = this.totalOf(c);
97	    const blk = this.block({ p: c.p, b: c.b });
98	    const tb = total && total.x;
99	    if (!tb && !terms.length) return null;
100	    const mid = (a, b) => (a + b) / 2;
101	    const labelX = blk && blk.x ? blk.x[0] : Math.min(...terms.map(t => t.x[0])) - 20;
102	    if (c.k === 'col' || c.k === 'grand_row') {
103	      const x = tb ? mid(tb[0], tb[2]) : mid(terms[0].x[0], terms[0].x[2]);
104	      const y1 = terms.length ? Math.min(...terms.map(t => t.x[1])) : (blk && blk.x ? blk.x[1] : tb[1]);
105	      return { x1: x, y1, x2: x, y2: tb ? mid(tb[1], tb[3]) : Math.max(...terms.map(t => t.x[3])) };
106	    }
107	    const ys = terms.length ? terms.map(t => mid(t.x[1], t.x[3])) : [mid(tb[1], tb[3])];
108	    const y = ys.reduce((a, b) => a + b, 0) / ys.length;
109	    const x2 = tb ? tb[2] : Math.max(...terms.map(t => t.x[2]));
110	    return { x1: labelX, y1: y, x2, y2: y };
111	  }
112	  // the report layout: a row's sum is a band across the row; a contest's column sum is a band down the figures' column to the
113	  // contest total row (null where the ink gave no column)
114	  reportBand(c) {
115	    const mid = b => (b[1] + b[3]) / 2, tv = this.totalOf(c);
116	    if (c.k === 'report_row') {
117	      const t = this.termsOf(c).find(x => x.x) || (tv && tv.x ? tv : null);
118	      if (!t) return null;
119	      const y = mid(t.fx || t.x);
120	      return { x1: t.x[0], y1: y, x2: t.x[2], y2: y };
121	    }
122	    if (!tv || !tv.x) return null;
123	    const terms = this.termsOf(c).filter(t => t.x && t.p === tv.p);
124	    const col = [tv, ...terms].map(t => t.fx).find(Boolean);
125	    if (!col || !terms.length) return null;
126	    const x = (col[0] + col[2]) / 2;
127	    return { x1: x, y1: Math.min(...terms.map(t => mid(t.fx || t.x))), x2: x, y2: mid(tv.fx || tv.x) };
128	  }
129	  // the printed figure's own box in page-image pixels, from the ink box of the block image; null without one
130	  inkPage(v) {
131	    const b = this.block(v);
132	    if (!v.ix || !b || !b.bi || !b.x) return null;
133	    const mx = b.bi.w / (b.x[2] - b.x[0]), my = b.bi.h / (b.x[3] - b.x[1]);
134	    return [b.x[0] + v.ix[0] / mx, b.x[1] + v.ix[1] / my, b.x[0] + v.ix[2] / mx, b.x[1] + v.ix[3] / my];
135	  }
136	  // the value to turn the sheet to for a sum: its first term with a box, else its printed total
137	  firstValue(c) {
138	    const t = this.termsOf(c).find(x => x.x);
139	    if (t) return t.i;
140	    const tot = this.totalOf(c);
141	    if (tot && tot.x) return tot.i;
142	    const any = this.termsOf(c)[0] || tot;   // nothing has a box: the loupe says so
143	    return any ? any.i : null;
144	  }
145	  // the opening value: page 1, both sums hold, read as accepted
146	  defaultOn(page) {
147	    if (this.report) {
148	      const list = this.byPage.get(page) || [];
149	      const good = i => { const v = this.values[i]; return v.x && v.s === 'accepted' && this.sumsFor(v).length > 0 && this.sumsFor(v).every(s => s.check.ok); };
150	      const i = list.find(good) ?? list.find(i => this.values[i].x);
151	      return i === undefined ? null : i;
152	    }
153	    const ok = v => !isTotal(v) && v.x && v.s === 'accepted' && this.sumsFor(v).length === 2 && this.sumsFor(v).every(s => s.check.ok);
154	    const list = this.byPage.get(page) || [];
155	    const i = list.find(i => ok(this.values[i])) ?? list.find(i => this.values[i].x);
156	    return i === undefined ? null : i;
157	  }
158	  // the label of a value as printed on the scan (the block's candidate, else its contest)
159	  printedLabel(v) { if (this.report) return v.r; const b = this.block(v); return b ? b.cand || b.contest || '' : ''; }
160	  rowLabel(v) { if (this.report) return v.r; return this.rowLabelM(v); }
161	  rowLabelM(v) { return v.r === 'col' ? 'Total' : v.r === 'row' ? 'Row total' : v.r === 'grand' ? 'Grand total' : v.r; }
162	  colLabel(v) { if (this.report) return COL_WORD[v.c] || v.c; return this.colLabelM(v); }
163	  colLabelM(v) { return v.r === 'grand' ? '' : v.r === 'row' ? '' : `precinct ${v.c}`; }
164	}
