11	// the other finding of the group that holds the value this one's scan has (a swap): where the file put it
12	export function siblingOf(store, f) {
13	  const g = store.groupById.get(f.group);
14	  if (!g || f.scan === undefined || f.file === undefined) return null;
15	  const sibs = g.findings.map(id => store.itemById.get(id)).filter(o => o && o.id !== f.id && (o.precinct !== f.precinct || o.part !== f.part));
16	  return sibs.find(o => o.file === f.scan && o.scan === f.file) || null;
17	}
