19	// the one plain sentence for what kind of slip this is
20	export function sentence(store, f) {
21	  const sib = siblingOf(store, f);
22	  const v = f.ref === undefined ? null : store.values[f.ref];
23	  if (store.report) return reportSentence(store, f, sib);
24	  if (f.scan === undefined && (f.kind === 'wrong_column' || f.kind === 'wrong_precinct')) {
25	    return `The file has ${val(f.file)} under precinct ${f.precinct}${f.part && f.part !== 'votes' ? `, ${PART[f.part]}` : ''}. The scan has no value there.`;
26	  }
27	  switch (f.kind) {
28	    case 'wrong_column':
29	      return `On the scan this vote is under ${v ? v.r : PART[f.part] || 'one column'}. ` +
30	        (sib ? `The file has it under ${PART[sib.part] || 'another column'}.` : 'The file has it under another column.');
31	    case 'wrong_precinct':
32	      return `On the scan this value is under precinct ${f.precinct}. ` +
33	        (sib ? `The file has it under precinct ${sib.precinct}.` : 'The file has it under another precinct.');
34	    case 'missing_row': return 'The scan has this value. The file has no row for it.';
35	    case 'extra_row': return 'The file has a row here that is not on the scan.';
36	    case 'file_row_fails_own_total': return "The parts of this row in the file do not add to the row's own total in the file.";
37	    default: return 'The file and the scan give different numbers for this one value.';
38	  }
39	}
