41	// the report layout: the figures of the row that differ between the file's row and the scan's row (indexes into COLS)
42	export const differs = f => (f.rv && f.rv.file && f.rv.scan ? COLS.map((_, k) => k).filter(k => f.rv.file[k] !== f.rv.scan[k]) : []);
43	function reportSentence(store, f, sib) {
44	  if (f.scan === undefined && f.kind !== 'extra_row') return `The file has ${val(f.file)} under ${pcl(f.precinct)}${f.part && f.part !== 'votes' ? `, ${PART[f.part]}` : ''}. The scan has no value there.`;
45	  switch (f.kind) {
46	    case 'wrong_column':
47	      return `On the scan this vote is under ${PART[f.part] || 'one column'}. ` + (sib ? `The file has it under ${PART[sib.part] || 'another column'}.` : 'The file has it under another column.');
48	    case 'extra_row': return 'The file has a row here that is not on the scan.';
49	    case 'missing_row': return 'The scan has this row. The file has no row for it.';
50	    case 'file_row_fails_own_total': return "The parts of this row in the file do not add to the row's own total in the file.";
51	    default: {
52	      const n = differs(f).length;
