57	// the status in one plain line; in the report layout a row nothing can decide says why, from the finding's own sums
58	export function statusLine(store, f) {
59	  const st = STATUS[f.status] || { line: '' };
60	  if (!store.report || f.status !== 'cannot_verify') return st.line;
