383	// ---- the run's numbers, and the sentence about the reader
384	export function runFigures(fd) {
385	  const f = fd.figures || {}, info = fd.run_info || {};
386	  const out = [];
387	  const add = (label, n, unit) => { if (n !== undefined && n !== null) out.push([label, n, unit]); };
388	  add('cells audited', f.cells, 'cells');
389	  add('right on first read', f.right_first, 'cells');
390	  add('right after re-reads', f.right_after, f.right_after === 1 ? 'cell' : 'cells');
391	  add('re-read', f.reread, f.reread === 1 ? 'cell' : 'cells');
392	  add('disagreements', f.disagreements, 'values');
393	  add('settled', f.settled, 'values');
394	  if (info.metered_cost_estimate !== undefined) out.push(['model cost', `$${Number(info.metered_cost_estimate).toFixed(2)}`, 'US dollars']);
395	  const secs = runSeconds(info);
396	  if (secs !== undefined) out.push(['minutes', (secs / 60).toFixed(1), 'min']);
397	  return out.map(([label, n, unit]) => [label, typeof n === 'number' ? fmt(n) : n, unit]);
398	}
