400	export function readerSentence(fd) {
401	  const info = fd.run_info || {}, s = info.sample;
402	  if (!s || !info.reader || s.row_sums === undefined || s.failing === undefined || !s.sampled_with) return '';
403	  const pages = [...new Set((s.blocks || []).map(b => (/^p(\d+)-/.exec(b) || [])[1]).filter(Boolean))];
404	  const what = !s.blocks ? 'A sample' : pages.length === 1 && pages[0] === '1' ? 'A sample of the first page' : 'A sample of a few pages';   // the run may not say which pages
405	  return `${what} read with ${s.sampled_with} failed ${fmt(s.failing)} of ${fmt(s.row_sums)} row sums, so this county was read with ${info.reader}.`;
406	}
