66	  const own = f.ref;
67	  const rows = s.terms.map(([ref, val]) => {
68	    const v = ref === null || ref === undefined ? null : store.values[ref];
69	    // the report layout: every figure of the sum that a finding names shows the file's value (the sum's file column adds those)
70	    const at = store.report && ref !== null && ref !== undefined && store.fileAt.has(ref);
71	    const diff = store.report ? at : own !== undefined && ref === own;
72	    const fileV = store.report ? (at ? store.fileAt.get(ref) : val) : f.file;
73	    return { label: v ? kindLabel(s.kind, v) : '…', scan: fmt(val), file: diff ? (fileV === undefined ? '—' : fmt(fileV)) : fmt(val), diff, ref: v ? ref : undefined };
74	  });
75	  if (!rows.some(r => r.diff) && f.kind === 'extra_row' && f.file !== undefined) {
76	    // a row only the file has: no term of the scan's sum is it
77	    rows.push({ label: 'file only', scan: '—', file: fmt(f.file), diff: true });
78	  }
79	  // long sums: the first term, the term that differs, the last, and a line for each run of terms left out between them
80	  // (a run of one is shown as the term itself)
81	  if (rows.length <= 5) return rows;
82	  const keep = new Set([0, rows.length - 1]);
83	  rows.forEach((r, i) => { if (r.diff) keep.add(i); });
84	  const out = []; let gap = [];
85	  const flush = () => { if (gap.length === 1) out.push(gap[0]); else if (gap.length) out.push({ label: `… ${gap.length} more`, scan: '', file: '', more: true }); gap = []; };
86	  rows.forEach((r, i) => { if (keep.has(i)) { flush(); out.push(r); } else gap.push(r); });
87	  flush();
88	  return out;
89	}
