110	    const pair = (cls, a, b, pick) => {
111	      const row = el('div', 'pair' + (cls ? ' ' + cls : ''));
112	      for (const side of [a, b]) {
113	        const cell = el('div', 'ln' + (side.diff ? ' diff' : '') + (side.cls ? ' ' + side.cls : ''));
114	        const lab = el('span', '', side.label);
115	        if (this.root.classList.contains('rep')) lab.title = side.label;   // a long row label may be cut with an ellipsis
116	        if (side.diff) lab.append(el('span', 'sr', ' (differs)'));
117	        cell.append(lab, el('span', '', side.fig));
118	        if (pick && side.ref !== undefined && !side.diff) {   // the value itself is already selected
119	          const bt = el('button', 'ln pick' + (side.diff ? ' diff' : ''));
120	          bt.type = 'button'; bt.append(...cell.children);
121	          bt.addEventListener('click', () => this.onPick(side.ref));
