123	        } else row.append(cell);
124	      }
125	      return row;
126	    };
127	    if (!f.sums.length) this.root.append(el('p', 'empty', 'No printed sum was recorded through this value.'));
128	    f.sums.forEach((s, n) => {
129	      const box = el('div', 'sum two');
130	      const h3 = el('h3', 'sr', sumHeading(s, f, store));
131	      box.append(h3);
132	      const heads = el('div', 'pair heads');
133	      heads.setAttribute('aria-hidden', 'true');   // the same words are in the heading above and in the lines
134	      heads.append(el('h4', '', `Public file · ${sumName(s, f, store)}`), el('h4', '', `Scan · ${sumName(s, f, store)}`));
135	      box.append(heads);
