152	      more.append(el('h3', '', 'Other printed sums through this value'));
153	      this.root.append(more);
154	      for (const { check: c } of others) {
155	        const box = el('div', 'sum quiet');
156	        box.append(el('h3', '', heading(c)));
157	        const sub = el('div', 'one');
158	        for (const l of termLines(store, c)) sub.append(line(l.label, l.fig, l.more ? 'more' : '', null));
159	        sub.append(line('adds to', fmt(c.co), 'rule'), line('printed total', fmt(c.pr)),
