189	    if (!animate || this.reduced) { steps.forEach(s => (s.style.visibility = '')); return; }
190	    const step = Math.min(STEP_MS, totalMs / steps.length);
191	    steps.forEach((s, i) => this.timers.push(setTimeout(() => { s.style.visibility = ''; }, i * step)));
