156	    const leaving = !first && animate && !this.reduced ? this.paper.cloneNode(true) : null;
157	    this.page = n;
158	    const pg = this.pg;
159	    this.stack.replaceChildren(...Array.from({ length: this.stackCount() }, (_, i) => {
160	      const e = document.createElement('i');
161	      const d = `calc(var(--inv, 1) * ${(i + 1) * STACK_PX}px)`;
162	      e.style.transform = `translate3d(${d}, ${d}, calc(var(--inv, 1) * ${-(i + 1) * 2}px))`;
163	      e.style.background = ['#c9c6b8', '#bfbcae', '#b5b2a4', '#abaa9b', '#a1a092'][i];
164	      return e;
165	    }));
166	    const depth = this.stackCount(), d = `calc(var(--inv, 1) * ${(depth + 1) * STACK_PX}px)`;
167	    const under = document.createElement('i');   // the contact shadow, lowest in the pile
168	    under.className = 'under';
169	    under.style.transform = `translate3d(${d}, ${d}, calc(var(--inv, 1) * ${-(depth + 1) * 2}px))`;
170	    this.stack.prepend(under);
171	    this.clearBands();
172	    this.anchor = null;
173	    this.layout(true);
174	    this.buildMarks();
175	    this.notice.hidden = true;
176	    this.setPartial(this.forcePartial);
177	    // a report county writes the image of the pages that carry a finding and page 1 only: the others are a blank sheet
178	    const blank = !pg.img;
179	    this.sheet.classList.toggle('blank', blank);
180	    if (this.blankNote) { this.blankNote.hidden = !blank; this.blankNote.textContent = blank ? `Page ${n}. No image of this page is included.` : ''; }
181	    if (blank) this.scan.removeAttribute('src');
182	    if (!this.forcePartial && !blank) await new Promise(res => {
183	      this.scan.onload = () => { loaded(); res(); };
184	      this.scan.onerror = () => {
185	        // no page image: the block's own image is shown flat instead, and only when there is none is it an error
186	        if (this.hasBlockImage()) this.setPartial(true);
187	        else { this.notice.textContent = this.onError(pg.img); this.notice.hidden = false; }
188	        res();
189	      };
190	      this.scan.src = pg.img;
191	    });
192	    if (leaving) {
193	      this.pump(PAGE_MS + 100);
194	      leaving.removeAttribute('id'); leaving.removeAttribute('role');
195	      leaving.querySelectorAll('[id]').forEach(e => e.removeAttribute('id'));
196	      leaving.style.pointerEvents = 'none';
197	      this.paper.before(leaving);
198	      leaving.animate([{ transform: 'translate3d(0,0,0)', opacity: 1 },
199	                       { transform: `translate3d(${-dir * this.sw * 0.7}px, ${this.sh * 0.08}px, 30px) rotateZ(${-dir * 5}deg)`, opacity: 0 }],
200	                      { duration: PAGE_MS, easing: 'cubic-bezier(.77,0,.175,1)' }).finished.then(() => leaving.remove(), () => leaving.remove());
201	      for (const e of [this.paper, this.marks])
202	        e.animate([{ transform: `translate3d(${dir * 6}px, 6px, -6px)` }, { transform: e === this.marks ? 'translateZ(.5px)' : 'none' }],
203	                  { duration: PAGE_MS, easing: 'cubic-bezier(.23,1,.32,1)' });
204	    }
205	  }
