207	  // ---- marks: one focusable rectangle per value that has a box
208	  buildMarks() {
209	    const pg = this.pg, m = this.marks;
210	    m.replaceChildren();
211	    m.setAttribute('viewBox', `0 0 ${pg.w} ${pg.h}`);
212	    this.bands.setAttribute('viewBox', `0 0 ${pg.w} ${pg.h}`);
213	    this.rects = [];
214	    for (const i of this.store.byPage.get(this.page) || []) {
215	      const v = this.store.values[i];
216	      if (!v.x) continue;
217	      const bx = this.store.report && v.fx ? v.fx : v.x;   // a figure of the report layout: its own box where the ink gave it, else its row
218	      const r = svg('rect', { x: bx[0], y: bx[1], width: bx[2] - bx[0], height: bx[3] - bx[1], tabindex: -1, role: 'button' });
219	      r.dataset.i = i; r.dataset.b = v.b;
220	      r.addEventListener('focus', () => { this.showFocus(bx); this.onFocusValue(i); });
221	      r.addEventListener('blur', () => { this.showFocus(null); setTimeout(() => { if (!this.marks.contains(document.activeElement)) this.onFocusValue(null); }); });
222	      if (this.store.isTotal(v)) r.classList.add('total');
223	      r.setAttribute('aria-label', `${v.v}, ${this.store.rowLabel(v)} ${this.store.colLabel(v)}`.trim());
224	      r.addEventListener('click', () => this.onPick(i));
225	      r.addEventListener('keydown', e => this.keys(e, r));
226	      m.append(r);
227	      this.rects.push({ r, i, cx: (bx[0] + bx[2]) / 2, cy: (bx[1] + bx[3]) / 2 });
228	    }
229	    this.ticks = new Map(); this.tickPaths = [];   // a hollow pencil circle at every finding's value on this page (the selected one has its ring instead)
230	    const tg = svg('g', { class: 'ticks', 'aria-hidden': 'true' });
231	    const rowSeen = new Map();
232	    for (const f of this.store.items) {
233	      const v = f.ref === undefined ? null : this.store.values[f.ref];
234	      if (!v || !v.x || v.p !== this.page) continue;
235	      if (this.store.report) {   // one mark per row: the row's figures share a box
236	        const key = `${v.b}:${v.r}`;
237	        if (rowSeen.has(key)) { this.ticks.set(f.ref, rowSeen.get(key)); continue; }
238	      }
239	      const g = svg('g', { transform: `translate(${v.x[0]} ${(v.x[1] + v.x[3]) / 2})`, class: 'tick ' + (f.status === 'settled_against_file' ? 'settled' : 'open') });
240	      const path = svg('circle', { cx: 8, cy: 0, r: 4.5 });   // 9 px across at the sheet's scale, 2 px stroke; hollow
241	      g.append(path);
242	      this.tickPaths.push(path);
243	      tg.append(g);
244	      this.ticks.set(f.ref, g);
245	      if (this.store.report) rowSeen.set(`${v.b}:${v.r}`, g);
246	    }
247	    m.prepend(tg);
248	    this.focusRing = svg('g', { class: 'focus-ring', 'aria-hidden': 'true' });
249	    for (const cls of ['dark', 'light']) this.focusRing.append(svg('rect', { class: cls }));
250	    this.focusRing.setAttribute('display', 'none');
251	    m.append(this.focusRing);
252	    this.markSelected();
253	  }
254	  // two strokes round the focused value, so it shows on white paper: ink outside, --focus inside, 2 px
255	  showFocus(b) {
256	    const g = this.focusRing;
257	    if (!g) return;
258	    if (!b) { g.setAttribute('display', 'none'); return; }
259	    for (const r of g.children) {
260	      r.setAttribute('x', b[0] - 1); r.setAttribute('y', b[1] - 1);
261	      r.setAttribute('width', b[2] - b[0] + 2); r.setAttribute('height', b[3] - b[1] + 2);
262	    }
263	    g.removeAttribute('display');
264	  }
265	  markSelected() {
266	    for (const [r, g] of this.ticks || []) { if (r === this.sel) g.setAttribute('display', 'none'); else g.removeAttribute('display'); }
267	    for (const o of this.rects || []) o.r.setAttribute('tabindex', o.i === this.sel ? 0 : -1);
268	    if (!this.rects.some(o => o.i === this.sel) && this.rects[0]) this.rects[0].r.setAttribute('tabindex', 0);
269	  }
270	  keys(e, r) {
271	    const i = +r.dataset.i;
272	    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); this.onPick(i); return; }
273	    const dirs = { ArrowRight: [1, 0], ArrowLeft: [-1, 0], ArrowDown: [0, 1], ArrowUp: [0, -1] };
274	    const d = dirs[e.key];
275	    if (!d) return;
276	    e.preventDefault();
277	    const cur = this.rects.find(o => o.i === i);
278	    let best = null, bs = Infinity;
279	    const inBlock = this.rects.filter(o => o.r.dataset.b === r.dataset.b);
280	    for (const o of this.rects.length && inBlock.some(o => o !== cur && (o.cx - cur.cx) * d[0] + (o.cy - cur.cy) * d[1] >= 4) ? inBlock : this.rects) {
281	      const dx = o.cx - cur.cx, dy = o.cy - cur.cy;
282	      const along = dx * d[0] + dy * d[1], across = Math.abs(dx * d[1] - dy * d[0]);
283	      if (along < 4) continue;
284	      const score = along + across * 4;
285	      if (score < bs) { bs = score; best = o; }
286	    }
287	    if (best) { r.setAttribute('tabindex', -1); best.r.setAttribute('tabindex', 0); best.r.focus(); }
288	  }
