290	  // ---- the bands
291	  clearBands() { this.bands.replaceChildren(); }
292	  async select(i, sums, animate = true, opts = {}) {
293	    const tk = ++this.token;
294	    this.sel = i;
295	    this.clearBands();
296	    this.markSelected();
297	    const instant = !animate || this.reduced;
298	    const first = sums.slice().sort((a, b) => (a.axis === 'row' ? -1 : 1) - (b.axis === 'row' ? -1 : 1));
299	    const v = this.store.values[i];
300	    let draws, ring;
301	    if (this.store.report) ({ draws, ring } = this.reportDraws(v, first, opts.extra || {}));
302	    else {
303	      draws = first.map(s => ({ ...s, line: this.store.band(s.check) })).filter(s => s.line);
304	      ring = v.x ? this.ringFor(v, draws) : null;
305	    }
306	    this.anchor = null;
307	    if (ring) {
308	      this.anchor = svg('circle', { cx: ring.x, cy: ring.y, r: ring.r, fill: 'none', stroke: 'none' });
309	      this.bands.append(this.anchor);
310	    }
311	    const loupeDraws = draws.map(d => ({ line: d.line, ok: d.check.ok, axis: d.axis }));
312	    if (this.loupe) this.loupe.show(this.store, i, loupeDraws, !instant, opts.extra || {});
313	    this.flatArgs = { v, draws: loupeDraws };
314	    if (this.partial) this.updateFlat();
315	    if (opts.settle) {   // the first load: the sheet settles from flat into its tilt
316	      const keep = { ...this.P };
317	      this.flat = false; this.base = this.fit();
318	      this.setP(keep);
319	    }
320	    if (v.x) this.go(this.target(), instant ? 0 : opts.settle ? ENTER_MS : TURN_MS);
321	    this.updateLeader();
322	    if (instant) {
323	      draws.forEach(s => this.band(s, true));
324	      if (ring) this.svgRing(ring, true);
325	      if (this.loupe) this.loupe.reveal(false);
326	      return true;
327	    }
328	    if (opts.settle) {   // the entrance: the sheet settles while the bands draw together, then the ring closes
329	      this.pump(ENTER_MS + 150);
330	      await wait(60);
331	      await Promise.all(draws.map(s => this.band(s, false, 260)));
332	      if (tk !== this.token) return false;
333	      await Promise.all([ring ? this.svgRing(ring, false, 120) : null, this.loupe ? this.loupe.reveal(true, 120) : null]);
334	      return tk === this.token;
335	    }
336	    this.pump(TURN_MS + 150);
337	    if (v.x) await wait(TURN_MS);
338	    for (const s of draws) {
339	      if (tk !== this.token) return false;
340	      await this.band(s, false);
341	    }
342	    if (tk !== this.token) return false;
343	    await Promise.all([ring ? this.svgRing(ring, false) : null, this.loupe ? this.loupe.reveal(true) : null]);
344	    return tk === this.token;
345	  }
346	  // a finding with no place on the sheet: nothing is ringed, no sum is drawn; the sheet stays where it is
347	  deselect() {
348	    this.token++;
349	    this.sel = null;
350	    this.clearBands();
351	    this.anchor = null;
352	    this.flatArgs = null;
353	    this.markSelected();
354	    this.go(this.target(), 0);
355	    this.updateLeader();
356	  }
357	  // the report layout: a band across the row (the row's own sum), a band down the figure's column to the contest total row
358	  // where that sum is in the finding, and the ring round the figure (else round the row's figures)
359	  reportDraws(v, sums, extra) {
360	    const st = this.store, f = extra.f || null;
361	    const draws = [];
362	    const rowSum = sums.find(s => s.axis === 'row'), colSum = sums.find(s => s.axis === 'col');
363	    const own = v.fx || null;
364	    const mid = b => (b[1] + b[3]) / 2;
365	    const y = own ? mid(own) : mid(v.x);
366	    if (rowSum) draws.push({ ...rowSum, line: { x1: v.x[0], y1: y, x2: v.x[2], y2: y } });
367	    const wantCol = colSum && (!f || f.sums.some(s => s.kind === 'report_contest'));
368	    if (wantCol) {
369	      const ti = st.totRow.get(`${v.b}:${v.c}`), tv = ti === undefined ? null : st.values[ti];
370	      const xc = own ? (own[0] + own[2]) / 2 : tv && tv.fx ? (tv.fx[0] + tv.fx[2]) / 2 : null;
371	      if (tv && tv.x && xc !== null) draws.push({ ...colSum, line: { x1: xc, y1: y, x2: xc, y2: tv.fx ? mid(tv.fx) : mid(tv.x) } });
372	    }
373	    const ok = draws.every(d => d.check.ok), hs = v.x[3] - v.x[1];
374	    let ring;
375	    if (own) ring = { x: (own[0] + own[2]) / 2, y: mid(own), r: Math.max(hs * 0.9, 20), ok };
376	    else {
377	      const fs = st.rowCells(v).map(j => (j === undefined ? null : st.values[j].fx)).filter(Boolean);
378	      const box = fs.length ? [Math.min(...fs.map(b => b[0])), Math.min(...fs.map(b => b[1])), Math.max(...fs.map(b => b[2])), Math.max(...fs.map(b => b[3]))]
379	                            : [v.x[2] - (v.x[2] - v.x[0]) * 0.45, v.x[1] + 4, v.x[2] - 6, v.x[3] - 4];
380	      ring = { x: (box[0] + box[2]) / 2, y: mid(box), r: Math.max((box[3] - box[1]) * 0.9, 20), ok, box };
381	    }
382	    return { draws, ring };
383	  }
384	  ringFor(v, draws) {
385	    const h = v.x[3] - v.x[1], ink = this.store.inkPage(v) || v.x;
386	    return { x: (ink[0] + ink[2]) / 2, y: (ink[1] + ink[3]) / 2, r: Math.max(h * 0.9, 20), ok: draws.every(d => d.check.ok) };
387	  }
388	  band(s, instant, ms = LINE_MS) {
389	    const { x1, y1, x2, y2 } = s.line;
390	    const l = svg('line', { x1, y1, x2, y2, class: s.check.ok ? 'holds' : 'fails' });
391	    this.bands.append(l);
392	    const len = Math.hypot(x2 - x1, y2 - y1);
393	    l.setAttribute('stroke-dasharray', `${len} ${len}`);
394	    if (instant) return Promise.resolve();
395	    return l.animate([{ strokeDashoffset: len }, { strokeDashoffset: 0 }], { duration: ms, easing: 'cubic-bezier(.23,1,.32,1)', fill: 'backwards' }).finished.catch(() => {});
396	  }
397	  svgRing(r, instant, ms = RING_MS) {
398	    const c = r.box ? svg('path', { d: loopPath(r.box, 6), class: r.ok ? 'holds' : 'fails', pathLength: 1000 })
399	                    : svg('circle', { cx: r.x, cy: r.y, r: r.r, class: r.ok ? 'holds' : 'fails' });
400	    c.style.opacity = 1;
401	    this.bands.append(c);
402	    const len = r.box ? 1000 : 2 * Math.PI * r.r;
403	    c.setAttribute('stroke-dasharray', `${len} ${len}`);
404	    if (!r.box) c.setAttribute('transform', `rotate(-90 ${r.x} ${r.y})`);
405	    if (instant) return Promise.resolve();
406	    return c.animate([{ strokeDashoffset: len }, { strokeDashoffset: 0 }], { duration: ms, easing: 'ease-out', fill: 'backwards' }).finished.catch(() => {});
407	  }
