409	  // ---- partial: no page image, so the block's own image is shown flat where the sheet would be
410	  hasBlockImage() { return this.store.blocks.size && [...this.store.blocks.values()].some(b => b.p === this.page && b.bi); }
411	  setPartial(on) {
412	    this.partial = on;
413	    this.root.classList.toggle('partial', on);
414	    const bs = document.body.dataset;
415	    if (on) bs.state = 'partial'; else if (bs.state === 'partial' && !this.forcePartial) bs.state = 'ready';
416	    this.flatEl.hidden = !on;
417	    if (on) { this.setLabel('The page image is not available. The block of the scan is shown flat.'); this.updateFlat(); }
418	    else this.flatEl.replaceChildren();
419	  }
420	  updateFlat() {
421	    const el = this.flatEl, a = this.flatArgs;
422	    el.replaceChildren();
423	    if (!a || !el.clientWidth) return;
424	    const { v, draws } = a, blk = this.store.block(v);
425	    if (!blk || !blk.bi || !blk.x) { const p = document.createElement('p'); p.textContent = 'No image of this block is available.'; el.append(p); return; }
426	    const { bi } = blk, W = el.clientWidth, H = el.clientHeight;
427	    const k = Math.min(0.75, H / bi.h);
428	    const mx = bi.w / (blk.x[2] - blk.x[0]), my = bi.h / (blk.x[3] - blk.x[1]);
429	    const X = x => (x - blk.x[0]) * mx, Y = y => (y - blk.x[1]) * my;
430	    const cx = v.ix ? (v.ix[0] + v.ix[2]) / 2 : v.x ? X((v.x[0] + v.x[2]) / 2) : 0;
431	    const tx = bi.w * k <= W ? (W - bi.w * k) / 2 : Math.min(0, Math.max(W - bi.w * k, W / 2 - cx * k));
432	    const pan = document.createElement('div');
433	    pan.className = 'fb-pan';
434	    pan.style.cssText = `width:${bi.w}px;height:${bi.h}px;transform:translate(${tx}px,${(H - bi.h * k) / 2}px) scale(${k})`;
435	    const img = document.createElement('img');
436	    img.alt = ''; img.src = bi.img; img.width = bi.w; img.height = bi.h;
437	    const o = svg('svg', { viewBox: `0 0 ${bi.w} ${bi.h}`, width: bi.w, height: bi.h, class: 'fb-svg', 'aria-hidden': 'true' });
438	    for (const d of draws) {
439	      if (!d.line) continue;
440	      const thick = d.axis === 'row' ? (v.x ? (v.x[3] - v.x[1]) * my : 48) : (v.x ? (v.x[2] - v.x[0]) * mx : 150);
441	      const l = svg('line', { x1: X(d.line.x1), y1: Y(d.line.y1), x2: X(d.line.x2), y2: Y(d.line.y2), class: d.ok ? 'holds' : 'fails' });
442	      l.style.strokeWidth = thick;
443	      o.append(l);
444	    }
445	    for (const j of this.store.byPage.get(blk.p) || []) {
446	      const q = this.store.values[j];
447	      if (q.b !== blk.id || !q.x) continue;
448	      const r = svg('rect', { x: X(q.x[0]), y: Y(q.x[1]), width: (q.x[2] - q.x[0]) * mx, height: (q.x[3] - q.x[1]) * my, class: 'fb-hit' });
449	      r.addEventListener('click', () => this.onPick(j));
450	      o.append(r);
451	    }
452	    if (v.x) {
453	      const box = v.ix || [X(v.x[0]), Y(v.x[1]), X(v.x[2]), Y(v.x[3])];
454	      const ring = svg('path', { d: v.ix ? loopPath(box, 8 / k) : boxPath(box, 4 / k), class: 'fb-ring ' + (draws.every(d => d.ok) ? 'holds' : 'fails') });
455	      ring.style.strokeWidth = 2.5 / k;
456	      o.append(ring);
457	    }
458	    pan.append(img, o);
459	    el.append(pan);
460	  }
