463	  setFlat(f, animate = true) {
464	    this.flat = f;
465	    if (!this.pg) return;
466	    const keep = { ...this.P };
467	    this.base = this.fit();
468	    const P = this.target();
469	    this.setP(keep);
470	    this.go(P, animate && !this.reduced ? FLAT_MS : 0);
