474	  // ---- the sheet leans toward the pointer, by at most 3 degrees
475	  watchPointer() {
476	    const t = this.lean;
477	    this.viewport.addEventListener('pointermove', e => {
478	      if (e.pointerType !== 'mouse') return;
479	      const b = this.viewport.getBoundingClientRect();
480	      const nx = ((e.clientX - b.left) / b.width) * 2 - 1, ny = ((e.clientY - b.top) / b.height) * 2 - 1;
481	      t.tx = -nx * LEAN_MAX; t.ty = ny * LEAN_MAX;
482	      this.tick();
483	    });
484	    this.viewport.addEventListener('pointerleave', () => { t.tx = 0; t.ty = 0; this.tick(); });
485	  }
486	  tick() {
487	    const t = this.lean;
488	    if (t.raf) return;
489	    const step = () => {
490	      t.x += (t.tx - t.x) * 0.12; t.y += (t.ty - t.y) * 0.12;
491	      const done = Math.abs(t.tx - t.x) < 0.01 && Math.abs(t.ty - t.y) < 0.01;
492	      if (done) { t.x = t.tx; t.y = t.ty; }
493	      this.leanEl.style.transform = `rotateX(${t.y}deg) rotateY(${t.x}deg)`;
494	      this.updateLeader();
495	      t.raf = done ? 0 : requestAnimationFrame(step);
496	    };
497	    t.raf = requestAnimationFrame(step);
498	  }
