1	// The replay: the run's own recorded events, played on the sheet in order. Nothing is invented: every step is built from
2	// an event or a figure in the county's data (see buildTimeline), and a step whose data is missing is left out.
3	//
4	// buildTimeline(d) is a plain function of the county's JSON (site/data/<county>.json, keys in crossfoot/sitebuild.py):
5	// no page, no DOM. The Replay class plays what it returns.
6	import { fmt, COL_WORD, COLS } from './data.js';
7	
8	const SVGNS = 'http://www.w3.org/2000/svg';
9	export const SPEEDS = [1, 2, 4];
10	// milliseconds a step lasts at the default speed
11	const MS = { sample: 2400, read: 200, readTurn: 420, check: 3000, suspect: 2700, audit: 3800, end: 1800 };
12	const CANCELLED = Symbol('replay cancelled');
13	
