407	      if (x && +m[1] === this.curPage) this.put(this.curPage, { type: 'rect', cls: 'frame', x });
408	    }
409	  }
410	  async readStep(s, tok) {
411	    if (s.first) this.clearLayer();
412	    await this.page(s.page, tok);
413	    const x = s.block ? this.boxOf(s.page, s.block) : this.pageBox(s.page);   // the report layout is read a page at a time
414	    if (x) this.put(s.page, { type: 'rect', cls: 'wash', x });
415	  }
416	  async checkStep(s, tok) {
417	    this.clearLayer();
418	    const checks = s.sums.map(k => this.store.chk.get(checkKey(k))).filter(Boolean);
419	    const pages = [...new Set(checks.map(c => c.p))].sort((a, b) => a - b);
420	    const each = (s.ms - 400) / Math.max(1, pages.length);
421	    for (const n of pages) {
422	      await this.page(n, tok);
423	      for (const c of checks.filter(c => c.p === n)) {
424	        const line = this.store.band(c);
425	        if (line) this.put(n, { type: 'line', cls: 'sum fails', ...line });
426	      }
427	      await this.sleep(Math.max(0, each - (this.animate ? 420 : 0)), tok);
428	    }
429	  }
430	  valueOf(s) {
431	    const { store } = this;
432	    if (s.entity) { const i = store.byId.get(s.entity.join(':')); if (i !== undefined) return i; }
433	    const c = s.sums.map(k => store.chk.get(checkKey(k))).find(Boolean);
434	    if (!c) return null;
435	    const t = store.totalOf(c);
436	    return t && t.x ? t.i : store.firstValue(c);
437	  }
438	  async suspectStep(s, tok) {
439	    const { store, stage, loupe } = this;
440	    const i = this.valueOf(s);
441	    this.clearLayer();
442	    if (i === null) return;                          // nothing on the sheet to point at: the step is left out
443	    const v = store.values[i], said = suspectCaptions(s);
444	    await this.page(v.p, tok);
445	    this.say(said.first);
446	    // the sums that run through the value, drawn as failing: that is what the run saw on the first read
447	    const mine = new Set(s.sums.map(checkKey));
448	    let sums = store.sumsFor(v);
449	    if (sums.some(x => mine.has(`${x.check.k}:${x.check.p}:${x.check.b}:${x.check.y}`))) sums = sums.filter(x => mine.has(`${x.check.k}:${x.check.p}:${x.check.b}:${x.check.y}`));
450	    sums = sums.map(x => ({ ...x, check: { ...x.check, ok: false } }));
451	    this.quietLoupe(false);
452	    const done = await stage.select(i, sums, this.animate, {});
453	    this.guard(tok);
454	    if (!done) return;
455	    await this.sleep(s.ms * 0.1, tok);
456	    if (said.then) {
457	      if (s.changed) loupe.setTag(`first read ${fmt(s.changed.old)} · read again ${fmt(s.changed.new)}`);
458	      if (said.ring) this.recolor(said.ring);
459	      this.say(said.then);
460	    }
461	  }
462	  // the lines and the ring of the value being looked at: holds (both sums hold now), or warn (the ring only: nothing decides it)
463	  recolor(cls) {
464	    for (const e of this.stage.bands.querySelectorAll('line')) e.setAttribute('class', cls === 'holds' ? 'holds' : 'fails');
465	    for (const e of this.stage.bands.querySelectorAll('circle[class]')) e.setAttribute('class', cls);
466	    this.loupe.setRing(cls);
467	  }
468	  async auditStep(s, tok) {
469	    const { store, stage } = this;
470	    this.clearLayer();
471	    stage.deselect();
472	    this.quietLoupe(true);
473	    this.loupe.hideTag();
474	    const all = this.items, per = (s.ms - 300) / Math.max(1, s.pages.length);
475	    document.body.classList.add('rp-ticks');
476	    let from = { all: 0, settled: 0, cannot: 0, doc: 0, confirmed: 0 };
477	    for (const n of s.pages) {
478	      await this.page(n, tok);
479	      stage.marks.querySelectorAll('.tick').forEach((t, k) => { t.classList.add('pop'); t.style.animationDelay = this.animate ? `${Math.min(k * 14, 400)}ms` : '0ms'; });
480	      const to = this.countsTo(all, n);
481	      await this.countUp(from, to, Math.min(per, 600), tok);
482	      from = to;
483	      await this.sleep(Math.max(0, per - 600), tok);
484	    }
485	    this.headline.full();
486	  }
487	  countsTo(items, page) {
488	    const got = items.filter(f => f.page !== undefined && f.page <= page);
489	    return { all: got.length, settled: got.filter(f => f.status === 'settled_against_file').length, cannot: got.filter(f => f.status === 'cannot_verify').length,
490	             doc: got.filter(f => f.status === 'document_inconsistent').length, confirmed: got.filter(f => f.confirmed_by_person).length };
491	  }
492	  countUp(a, b, ms, tok) {
493	    return new Promise((res, rej) => {
494	      const t0 = this.pos;
495	      const step = () => {
496	        if (tok !== this.tok) return rej(CANCELLED);
497	        const t = this.animate ? Math.min(1, (this.pos - t0) / ms) : 1;
498	        const at = {};
499	        for (const k in b) at[k] = Math.round(a[k] + (b[k] - a[k]) * t);
500	        this.headline.set(at);
501	        if (t < 1) requestAnimationFrame(step); else res();
502	      };
503	      requestAnimationFrame(step);
504	    });
505	  }
506	  async endStep(tok) {
507	    // the page goes back to its opening finding, drawn as on load; the page's own select must not stop this replay
508	    this.restoring = true;
509	    this.layer.replaceChildren(); this.mem.clear();
510	    this.headline.full();
511	    this.quietLoupe(false);
512	    try { await this.restore(this.animate); } finally { this.restoring = false; }
513	  }
514	}
