// The explaining half of the page: the hero and its worked example, the three steps, and the run. Everything on it comes from
// data/index.json and the county files; nothing is typed in here except the words around the figures.
import { fmt, PART, COLS, COL_WORD, pcl, cap } from './data.js';
import { loopPath } from './ring.js';
import { decidingSum, termTokens, placeOf } from './findings.js';

const SVGNS = 'http://www.w3.org/2000/svg';
const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text !== undefined) e.textContent = text; return e; };
const svg = (tag, attrs = {}) => { const e = document.createElementNS(SVGNS, tag); for (const k in attrs) e.setAttribute(k, attrs[k]); return e; };
const GITHUB = 'https://github.com/itssaharsh/crossfoot';
const DIGIT_PX = 34, DIGIT_MIN = 28;   // the figure in the example crop is drawn this tall on screen (never less than the minimum)

// the opening finding of a county: the first wrong-column group the printed sums all settled, else the first settled finding
export function opening(store) {
  const settled = f => f.status === 'settled_against_file';
  const g = store.fd.groups.find(g => g.kind === 'wrong_column' && g.findings.length && g.findings.every(id => settled(store.itemById.get(id))));
  if (g) { const fs = g.findings.map(id => store.itemById.get(id)); return fs.find(f => f.ref !== undefined) || fs[0]; }
  return store.items.find(f => settled(f) && f.ref !== undefined) || store.items.find(settled) || store.items[0];
}
export const startFinding = store => (store.report ? store.items[0] : opening(store));

// ---- the example crop: the scan's own pixels round the value, from the loupe's image
export function cropSpec(store, f) {
  if (f.ref === undefined) return null;
  const v = store.values[f.ref];
  if (!v) return null;
  if (store.report) {
    const rc = store.rowCrop(v), fb = rc && rc.fb && rc.fb[v.c];
    return fb ? { src: rc.img, w: rc.w, h: rc.h, box: fb.slice(), digit: fb[3] - fb[1] } : null;
  }
  const blk = store.block(v);
  if (!blk || !blk.bi || !blk.x || (!v.ix && !v.x)) return null;
  const mx = blk.bi.w / (blk.x[2] - blk.x[0]), my = blk.bi.h / (blk.x[3] - blk.x[1]);
  const box = v.ix ? v.ix.slice() : [(v.x[0] - blk.x[0]) * mx, (v.x[1] - blk.x[1]) * my, (v.x[2] - blk.x[0]) * mx, (v.x[3] - blk.x[1]) * my];
  return { src: blk.bi.img, w: blk.bi.w, h: blk.bi.h, box, digit: (box[3] - box[1]) * (v.ix ? 1 : 0.6) };
}

// the finding the picture is made of: the page's opening finding when it can be drawn, else the first settled one that can
export function pickExample(store) {
  if (!store || !store.fd || !store.items.length) return null;
  const ok = f => f && f.status === 'settled_against_file' && f.ref !== undefined && f.scan !== undefined && f.file !== undefined && decidingSum(f) && cropSpec(store, f);
  const first = startFinding(store);
  return ok(first) ? first : store.items.find(ok) || null;
}

// ---- the hero's words and figures
export function renderHeroText(index) {
  const t = index.totals || {};
  document.getElementById('headline').textContent = `${fmt(t.findings)} numbers in a public election dataset don't match the scanned originals.`;
  const figs = document.getElementById('figs');
  figs.replaceChildren(...[[t.read, 'county files checked'], [t.findings, 'mismatches found'], [t.settled, "proven by the scans' own totals"]].map(([n, l]) => {
    const li = el('li');
    li.append(el('span', 'n', fmt(n)), el('span', 'l', l));
    return li;
  }));
  const note = document.getElementById('figs-note');
  note.textContent = t.cannot_verify !== undefined ? `${fmt(t.cannot_verify)} could not be proven and were left alone.` : '';
  note.hidden = t.cannot_verify === undefined;
}

// ---- the worked example: the page lying in depth on a pale desk, the crop of the scan lifted above it
export function renderHeroPic(fig, store, f, index, firstPage) {
  fig.replaceChildren();
  if (!store || !f) return plainPage(fig, firstPage);
  const spec = cropSpec(store, f), v = store.values[f.ref], pg = store.pages.find(p => p.n === f.page);
  const s = decidingSum(f);
  const county = (index.counties.find(c => c.key === store.d.county) || {}).name || cap(String(store.d.county));
  const labels = el('div', 'hp-labels');
  const lScan = el('p', 'lab scan', `The scan says ${fmt(f.scan)}`), lFile = el('p', 'lab file', `The public file says ${fmt(f.file)}`);
  labels.append(lScan, lFile);
  const view = el('div', 'hp-view');
  const card = el('div', 'hp-crop');
  card.append(view);
  const top = el('div', 'hp-top');
  const lead = svg('svg', { class: 'hp-lead', 'aria-hidden': 'true' });
  top.append(labels, card, lead);
  const noun = ['col', 'report_contest', 'grand_row'].includes(s.kind) ? 'column' : s.kind === 'grand' ? 'set of totals' : 'row';
  const proof = el('p', 'hp-proof');
  proof.append(el('strong', '', 'Proof: '), `with the file's number this ${noun} adds up to ${fmt(s.with_file)}. The scan prints a total of ${fmt(s.printed)}.`);
  const cap_ = el('figcaption', 'hp-cap', `${county} County, page ${f.page} of the scan. A real example from this run.`);
  fig.append(top, proof, cap_);
  const sheet = pg && pg.img ? sheetScene(pg, v) : null;
  if (sheet) fig.append(sheet.wrap);

  // the crop: the figure at reading size, the pencil loop on it
  const img = el('img');
  img.alt = `A close crop of the scan. The ringed figure reads ${fmt(f.scan)}.`;
  img.src = spec.src; img.width = spec.w; img.height = spec.h;
  const pan = el('div', 'hp-pan');
  pan.style.width = `${spec.w}px`; pan.style.height = `${spec.h}px`;
  const ov = svg('svg', { viewBox: `0 0 ${spec.w} ${spec.h}`, width: spec.w, height: spec.h, class: 'hp-ov', 'aria-hidden': 'true' });
  const ring = svg('path', { d: loopPath(spec.box, 9), class: 'hp-ring' });
  ov.append(ring);
  pan.append(img, ov);
  view.append(pan);

  const place = () => {
    const W = view.clientWidth, H = view.clientHeight;
    if (!W || !H) return;
    const S = Math.max(DIGIT_MIN / spec.digit, Math.min(DIGIT_PX / spec.digit, 2.4));
    const cx = (spec.box[0] + spec.box[2]) / 2, cy = (spec.box[1] + spec.box[3]) / 2;
    let tx = W / 2 - cx * S, ty = H / 2 - cy * S;
    tx = spec.w * S <= W ? (W - spec.w * S) / 2 : Math.min(0, Math.max(W - spec.w * S, tx));
    ty = spec.h * S <= H ? (H - spec.h * S) / 2 : Math.min(0, Math.max(H - spec.h * S, ty));
    pan.style.transform = `translate(${tx}px, ${ty}px) scale(${S})`;
    ring.style.strokeWidth = `${3 / S}px`;
    if (sheet) sheet.fit(fig.clientWidth);
    // the two short leaders: from each label down into the crop, to the loop on the figure
    const o = top.getBoundingClientRect(), r = ring.getBoundingClientRect();
    lead.replaceChildren();
    for (const [lab, cls, fx] of [[lScan, 'scan', 0.3], [lFile, 'file', 0.7]]) {
      const b = lab.getBoundingClientRect();
      const x1 = b.left + b.width / 2 - o.left, y1 = b.bottom - o.top + 2;
      const x2 = r.left + r.width * fx - o.left, y2 = r.top + 6 - o.top;
      lead.append(svg('line', { x1, y1, x2, y2, class: cls }), svg('circle', { cx: x2, cy: y2, r: 3.5, class: cls }));
    }
    // a thin line from the crop down to the same figure on the sheet
    if (sheet) sheet.leader(lead, o, card);
  };
  requestAnimationFrame(place);
  new ResizeObserver(place).observe(fig);
  if (!img.complete) img.addEventListener('load', place);
}

function plainPage(fig, page) {
  if (!page) return;
  const wrap = el('div', 'hp-plain');
  const im = el('img');
  im.alt = `The first page of the scan of ${page.county}`; im.src = page.img;
  wrap.append(im);
  fig.append(wrap, el('figcaption', 'hp-cap', `${page.county} County, page ${page.n} of the scan.`));
}

// the scan page in depth: its page stack, a soft shadow, and a ring where the value is
function sheetScene(pg, v) {
  const wrap = el('div', 'hp-desk');
  const sheet = el('div', 'hp-sheet');
  const under = el('i', 'under');
  const pile = Array.from({ length: 4 }, (_, i) => {
    const e = el('i', 'leaf');
    e.style.transform = `translate3d(${(i + 1) * 3}px, ${(i + 1) * 3}px, ${-(i + 1) * 2}px)`;
    e.style.background = ['#e4e1d6', '#dad7cb', '#d0cdc0', '#c6c3b5'][i];
    return e;
  });
  under.style.transform = 'translate3d(15px, 15px, -10px)';
  const page = el('div', 'face');
  const im = el('img');
  im.alt = 'The whole scanned page, lying on a desk'; im.src = pg.img;
  const ov = svg('svg', { viewBox: `0 0 ${pg.w} ${pg.h}`, class: 'face-ov', 'aria-hidden': 'true' });
  const dot = v && v.x ? svg('circle', { cx: (v.x[0] + v.x[2]) / 2, cy: (v.x[1] + v.x[3]) / 2, r: Math.max((v.x[3] - v.x[1]) * 1.2, 22), class: 'face-ring' }) : null;
  if (dot) ov.append(dot);
  page.append(im, ov);
  sheet.append(under, ...pile, page);
  wrap.append(sheet);
  return {
    wrap,
    fit(w) {   // the sheet's width follows the picture; the box under it is as tall as the tilted sheet
      const sw = Math.min(w * 0.84, 560), sh = sw * pg.h / pg.w;
      sheet.style.width = `${sw}px`; sheet.style.height = `${sh}px`;
      wrap.style.height = `${Math.round(sh * 0.74 + 24)}px`;
    },
    leader(lead, o, card) {
      if (!dot) return;
      const r = dot.getBoundingClientRect(), c = card.getBoundingClientRect();
      if (!r.width) return;
      const x = r.left + r.width / 2 - o.left;
      lead.append(svg('line', { x1: Math.min(Math.max(x, c.left - o.left + 12), c.right - o.left - 12), y1: c.bottom - o.top, x2: x, y2: r.top + r.height / 2 - o.top, class: 'sheet' }));
    },
  };
}

// ---- how it works: three cards, each with a small real picture
const FILE_COLS = [['early_voting', 'Early'], ['absentee', 'Absentee'], ['election_day', 'Election day'], ['votes', 'Total']];
// three rows of the published file round the example: [{label, cells: [{v, bad}]}], with the header words
export function neighbourRows(store, f) {
  const v = store.values[f.ref];
  const cell = (p, b, r, c) => { const i = store.byId.get(`${p}:${b}:${r}:${c}`); return i === undefined ? null : i; };
  const cellOf = (i) => { const o = store.fileAt.has(i) ? { v: store.fileAt.get(i), bad: true } : { v: store.values[i].v, bad: false }; return o; };
  if (store.report) {
    const rows = [];
    for (const i of store.byPage.get(v.p) || []) { const o = store.values[i]; if (o.b === v.b && !rows.includes(o.r)) rows.push(o.r); }
    const k = rows.indexOf(v.r), pick = rows.slice(Math.max(0, k - 1), k + 2);
    const out = pick.map(r => ({ label: r, cells: COLS.map(c => { const i = cell(v.p, v.b, r, c); return i === null ? null : cellOf(i); }) })).filter(r => r.cells.every(Boolean));
    return { head: COLS.map(c => cap(COL_WORD[c])), rows: out, title: [f.precinct ? cap(pcl(f.precinct)) : null, f.office].filter(Boolean).join(' · ') };
  }
  const blk = store.block(v);
  const peers = [...store.blocks.values()].filter(b => b.p === v.p && b.cand && blk && b.contest === blk.contest);
  const k = peers.findIndex(b => b.id === v.b), pick = peers.slice(Math.max(0, k - 1), k + 2);
  const KIND_ROWS = ['EARLY', 'ABSENTEE', 'PRECINCT', 'col'];
  const out = pick.map(b => ({ label: b.cand, cells: KIND_ROWS.map(r => { const i = cell(v.p, b.id, r, v.c); return i === null ? null : cellOf(i); }) })).filter(r => r.cells.every(Boolean));
  return { head: FILE_COLS.map(c => c[1]), rows: out, title: [f.precinct ? cap(pcl(f.precinct)) : null, blk && blk.contest].filter(Boolean).join(' · ') };
}

export function renderSteps(box, store, f, firstPage) {
  box.replaceChildren();
  const card = (n, title, text, pic) => {
    const li = el('li', 'step');
    li.append(el('p', 'pic', ''), el('h3', '', `${n} · ${title}`), el('p', '', text));
    li.firstChild.replaceWith(pic);
    box.append(li);
  };
  // 1: a thumbnail of a real scanned page
  const pg1 = (store && f && store.pages.find(p => p.n === f.page && p.img)) || null;
  const src = pg1 ? { img: pg1.img, county: (store.d.county || '') } : firstPage;
  const p1 = el('div', 'pic thumb');
  if (src) { const im = el('img'); im.src = src.img; im.alt = 'A scanned page of county results: a printed table, as a picture'; p1.append(im); }
  card(1, 'A county publishes a scan', 'A picture of a printed table. There is no text in it to copy.', p1);
  // 2: three rows of the published file, the wrong cell marked red
  const p2 = el('div', 'pic minitable');
  const nb = store && f ? neighbourRows(store, f) : null;
  if (nb && nb.rows.length) {
    const cap_ = el('p', 'mt-title', `The published file · ${nb.title}`);
    const t = el('table');
    t.setAttribute('aria-label', `Three rows of the published file round the example. ${nb.title}`);
    const head = el('tr');
    head.append(el('th', '', ''), ...nb.head.map(h => Object.assign(el('th', 'num', h), { scope: 'col' })));
    head.firstChild.scope = 'col'; head.firstChild.append(el('span', 'sr', 'Row'));
    t.append(Object.assign(el('thead'), {}));
    t.firstChild.append(head);
    const tb = el('tbody');
    for (const r of nb.rows) {
      const tr = el('tr');
      const th = el('th', 'rowh', r.label); th.scope = 'row'; th.title = r.label;
      tr.append(th, ...r.cells.map(c => { const td = el('td', 'num' + (c.bad ? ' bad' : ''), fmt(c.v)); if (c.bad) td.append(el('span', 'sr', ' (wrong in the file)')); return td; }));
      tb.append(tr);
    }
    t.append(tb);
    p2.append(cap_, t);
  } else if (nb || !store) p2.append(el('p', 'mt-title', 'The published file is a spreadsheet of typed numbers.'));
  card(2, 'Volunteers type it into a spreadsheet', 'With thousands of numbers, slips get through, and nobody re-reads every page.', p2);
  // 3: the example's sum, two short lines
  const p3 = el('div', 'pic sums');
  const s = f ? decidingSum(f) : null;
  if (s) {
    for (const [who, side, total, holds] of [['Scan', 'scan', s.with_scan, s.holds_scan], ['File', 'file', s.with_file, s.holds_file]]) {
      const line = el('p', 'sumline ' + (holds ? 'holds' : 'fails'));
      const terms = el('span', 'terms');
      termTokens(store, f, s, side).forEach((k, i) => { if (i) terms.append(' + '); if (k.diff) terms.append(el('strong', 'chg', k.t)); else terms.append(k.t); });
      terms.append(` = ${fmt(total)}`);
      line.append(el('span', 'who', who), terms, ' ', Object.assign(el('span', 'tick', holds ? '✓' : '✗'), { ariaHidden: 'true' }), el('span', 'sr', holds ? ', matches the printed total' : ', does not match the printed total'));
      p3.append(line);
    }
    p3.append(el('p', 'mt-title', `printed total ${fmt(s.printed)}`));
  } else p3.append(el('p', 'mt-title', 'Every printed table adds up to its own totals.'));
  card(3, 'Crossfoot reads the scan again and adds it up', "Every table prints its own totals. A number is called wrong only when those totals prove it.", p3);
}

// ---- the run
const EVIDENCE = `${GITHUB}/blob/main/docs/evidence/`;
const LINKS = [['Before and after', 'before-after.md'], ['The one-prompt baseline', 'baseline.md'], ['Recoveries', 'recovery.md'], ['Traces', 'traces.md']];
const listWords = names => (names.length <= 1 ? names.join('') : `${names.slice(0, -1).join(', ')} and ${names[names.length - 1]}`);

// the counties whose first sample failed more than the line, so the stronger reader was used: from the sample figures the run kept
export function switchedCounties(index, samples) {
  return index.counties.filter(c => {
    const s = samples.get(c.key);
    return s && s.row_sums && s.failing / s.row_sums > s.line && s.reader !== s.sampled_with;
  }).map(c => c.name);
}

export function renderRun(box, index, samples) {
  box.querySelectorAll('.run-body').forEach(n => n.remove());
  const t = index.totals || {};
  const body = el('div', 'run-body');
  const mins = t.seconds !== undefined ? (t.seconds / 60).toFixed(1) : null;
  const bits = [];
  if (t.counties !== undefined) bits.push(`audited all ${fmt(t.counties)} files`);
  if (mins) bits.push(`in ${mins} minutes`);
  const cost = t.metered_cost !== undefined ? ` for $${Number(t.metered_cost).toFixed(2)} of model calls${t.model_calls !== undefined ? ` (${fmt(t.model_calls)} calls)` : ''}` : '';
  if (bits.length) body.append(el('p', 'run-line', `One command ${bits.join(' ')}${cost}.`));
  if (t.sums_in_all) {
    const g = el('div', 'bars');
    g.append(el('h3', '', 'Printed sums that hold'));
    for (const [label, n, cls] of [['In the published files', t.holding_published, 'pub'], ['In the corrected files', t.holding_corrected, 'cor']]) {
      if (n === undefined) continue;
      const row = el('div', 'bar-row ' + cls);
      const track = el('div', 'track');
      track.setAttribute('role', 'img');
      track.setAttribute('aria-label', `${label}: ${fmt(n)} of ${fmt(t.sums_in_all)} printed sums hold`);
      const fill = el('i'); fill.style.width = `${(n / t.sums_in_all * 100).toFixed(2)}%`;
      track.append(fill);
      const val = el('p', 'bv');
      val.append(el('strong', '', fmt(n)), ` of ${fmt(t.sums_in_all)}`);
      row.append(el('p', 'bl', label), track, val);
      g.append(row);
    }
    body.append(g);
  }
  const sw = switchedCounties(index, samples);
  body.append(el('p', 'reader', `The agent read a sample of each county with a cheap model first and switched to a stronger one only where more than a tenth of the sample's sums failed: ${sw.length ? listWords(sw) : 'no county needed that'}.`));
  const ul = el('ul', 'evid');
  for (const [label, file] of LINKS) { const li = el('li'); const a = el('a', '', label); a.href = EVIDENCE + file; li.append(a); ul.append(li); }
  body.append(el('h3', 'evid-h', 'The evidence, on GitHub'), ul);
  box.append(body);
}

import { getJSON, LoadError, loadMessage, Store, progress, fmt, NOT_CHECKED, cap } from './data.js';
import { Cards, emptyLine } from './cards.js';
import { Stage } from './stage.js';
import { Loupe } from './loupe.js';
import { Tape } from './tape.js';
import { renderFindingPanel, FindingList, Dialog, siblingOf, tagText, stageLabel, contextless } from './findings.js';
import { Replay } from './replay.js';
import { renderHeroText, renderHeroPic, renderSteps, renderRun, pickExample, startFinding } from './hero.js';
import { runSeconds } from './findings.js';

const $ = id => document.getElementById(id);
const q = new URLSearchParams(location.search);
const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
const coarse = matchMedia('(pointer: coarse)').matches;
const FIRST_RUN = 'No run has been built into this page yet. Run crossfoot site build.';
const STATES = ['loading', 'error', 'empty', 'partial', 'first-run'];
const sorted = c => c.t.slice().sort((a, b) => a - b).join(',');
const scrollTo = el => el.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', block: 'start' });

// ?reset=1 opens the page as if for the first time: no state, cell or flat parameter is read, and the address is cleaned
const reset = q.get('reset') === '1';
if (reset) { q.delete('reset'); for (const k of ['state', 'cell', 'flat']) q.delete(k); history.replaceState(null, '', location.pathname + (q.toString() ? '?' + q : '')); }
const forced = !reset && STATES.includes(q.get('state')) ? q.get('state') : null;
if (q.get('record') === '1') document.body.classList.add('record');   // recording mode: larger type for a screen capture, nothing hidden

const state = { key: null, cards: null, replay: null, opening: null, store: null, flist: null, sel: null, finding: null, index: null,
                stores: new Map(), first: true, hero: null, openTok: 0, everyOpen: false, enter: false };

const stage = new Stage({
  viewport: $('viewport'), leanEl: $('lean'), pose: $('pose'), paper: $('paper'), sheet: $('sheet'), stack: $('stack'), root: $('stage'),
  loupeEl: $('loupe'), leader: $('leader'), leaderLine: $('leader-line'),
  scan: $('scan'), bands: $('bands'), marks: $('marks'), notice: $('snotice'), flatEl: $('flatblock'),
}, { reduced, coarse, onPick: i => pickRef(i), onError: loadMessage, onStep: d => step(d) });
const loupe = new Loupe({ root: $('loupe'), view: $('lp-view') }, { onPick: i => pickRef(i), reduced });
stage.setLoupe(loupe);
const dialog = new Dialog($('dlg'));

// the tape sits in a disclosure inside the panel; one tape and one disclosure serve every finding
const every = document.createElement('details');
every.className = 'every';
const tapeHost = document.createElement('div');
tapeHost.className = 'tapewrap';
const tapeEl = document.createElement('section');
tapeEl.className = 'tape';
tapeEl.setAttribute('aria-label', 'The arithmetic');
tapeHost.append(tapeEl);
const tape = new Tape(tapeEl, reduced);

// ---- the page's state: body[data-state] decides what shows (styles.css); the controls follow it
function setState(name) {
  document.body.dataset.state = name;
  const live = !['loading', 'error', 'first-run'].includes(name);
  for (const id of ['flat', 'prev', 'next']) $(id).disabled = !live;
  const sb = $('statebox');
  if (name === 'loading') sb.textContent = `Loading run… ${progress.n} ${progress.n === 1 ? 'file' : 'files'}`;
  else if (name === 'first-run') sb.textContent = FIRST_RUN;
  else sb.textContent = '';
}
progress.on = () => { if (document.body.dataset.state === 'loading') setState('loading'); };

function fail(file) {
  $('notice').textContent = loadMessage(file);
  $('notice').hidden = false;
  setState('error');
}
// one county that cannot be loaded: the rest of the page stays
function localError(file) {
  const x = $('xpanel');
  x.dataset.kind = 'error';
  $('xnotice').textContent = loadMessage(file);
  $('xnotice').hidden = false;
  $('county-msg').hidden = true;
}

const getStore = async entry => {
  if (state.stores.has(entry.key)) return state.stores.get(entry.key);
  const s = new Store(await getJSON(entry.file));
  state.stores.set(entry.key, s);
  return s;
};

// ---- selection: a finding of the county; the sheet turns to its page, the loupe shows the scan, the panel says what is wrong
const pickRef = i => { const f = state.store && state.store.itemByRef.get(i); if (f) selectFinding(f); };
const selectFinding = (f, o) => { state.enter = false; return f.ref !== undefined ? selectValue(f, o) : selectPlaceless(f, o); };

function afterLoupe() { if (loupe.toggled) { loupe.toggled = false; stage.layout(true); } }

function renderPanel(f) {
  const { store } = state;
  renderFindingPanel($('panel'), store, f, {
    onCrop: (x, b) => dialog.crop(store, x, b), onEvidence: (x, b) => dialog.evidenceFile(store, x, b),
    details: every, tapeHost, open: state.everyOpen, onToggle: on => { state.everyOpen = on; },
  });
}

async function selectValue(f, { animate = true, entrance = false, settle = false } = {}) {
  if (state.replay) state.replay.stop();      // a selection by hand ends the replay
  const { store } = state;
  const i = f.ref, v = store.values[i];
  if (!v) return;
  document.body.classList.remove('idle');
  state.sel = i; state.finding = f;
  const sums = store.sumsFor(v);
  renderPanel(f);
  stage.setLabel(stageLabel(store, f));
  state.flist.select(f.id);
  updateCounter();
  const dec = new Set(f.sums.map(s => s.terms.map(t => t[0]).filter(x => x !== null && x !== undefined).sort((a, b) => a - b).join(',')));
  tape.printFinding(store, f, sums.filter(s => !dec.has(sorted(s.check))), false);
  if (v.p !== stage.page) await stage.setPage(v.p, animate, v.p > stage.page ? 1 : -1);
  const sib = f.kind === 'wrong_column' ? siblingOf(store, f) : null;
  const extra = { tag: tagText(store, f), f };
  if (sib && sib.ref !== undefined) extra.other = sib.ref;
  await stage.select(i, sums, animate, { settle, extra });
  afterLoupe();
}

// a finding the sheet has no place for: the group's crop, and no ring
async function selectPlaceless(f, { animate = true } = {}) {
  if (state.replay) state.replay.stop();
  const { store } = state;
  document.body.classList.remove('idle');
  state.sel = null; state.finding = f;
  renderPanel(f);
  stage.setLabel(`${stageLabel(store, f)} This value has no place on the sheet.`);
  state.flist.select(f.id);
  updateCounter();
  tape.printFinding(store, f, [], false);
  if (f.page && f.page !== stage.page) await stage.setPage(f.page, animate, f.page > stage.page ? 1 : -1);
  stage.deselect();
  const g = store.groupById.get(f.group);
  if (g && g.crop) loupe.showCrop(g.crop, `The scan around ${f.row || 'the row'}, as cropped by the audit`, animate);
  else loupe.clear();
  afterLoupe();
}

// Previous and Next: the county's findings in the order of the list, the page follows
function step(d) {
  const fl = state.flist;
  if (!fl || !fl.vis.length) return;
  const n = fl.vis.length, cur = state.finding ? fl.position(state.finding.id) : 0;
  const k = cur ? cur - 1 + d : d > 0 ? 0 : n - 1;
  if (k < 0 || k >= n || (cur && k === cur - 1)) return;
  selectFinding(fl.at(k));
}
function updateCounter() {
  const fl = state.flist, n = fl ? fl.vis.length : 0, cur = fl && state.finding ? fl.position(state.finding.id) : 0;
  $('counter').textContent = n ? `${cur ? fmt(cur) : '–'} of ${fmt(n)}` : '';
  $('prev').disabled = !n || cur === 1;
  $('next').disabled = !n || cur === n;
}
function setFlatLabel() { $('flat').textContent = stage.flat ? 'Tilt sheet' : 'Lay flat'; }

// ---- a county
async function openCounty(key, { push = false, wantFinding = null } = {}) {
  const tok = ++state.openTok;
  if (state.replay) { state.replay.stop(); state.replay = null; }
  const entry = state.index.counties.find(c => c.key === key);
  state.cards.select(key);
  state.key = key; state.enter = false;
  if (push) { q.set('county', key); for (const k of ['cell', 'finding']) q.delete(k); history.replaceState(null, '', location.pathname + '?' + q); }
  const x = $('xpanel');
  x.setAttribute('aria-labelledby', `tab-${key}`);
  $('xnotice').hidden = true;
  if (entry.status === 'unchecked') return openUnchecked(entry);
  let store;
  try { store = await getStore(entry); } catch (e) { localError(e.file || entry.file); return; }
  if (tok !== state.openTok) return;
  state.store = store;
  stage.setStore(store);
  stage.forcePartial = forced === 'partial';
  if (state.flist) state.flist.destroy();
  const none = forced === 'empty';
  state.flist = new FindingList($('flist'), store, { onPick: f => selectFinding(f), none, filterEl: $('filters'), statusEl: $('fshowing'), onChange: filterChanged });
  const hasFindings = !!store.fd && store.items.length > 0 && !none;
  if (!hasFindings) return openEmpty(store, entry, none);
  $('findings-h').textContent = `All ${store.items.length === 1 ? 'mismatch' : `${fmt(store.items.length)} mismatches`} in ${entry.name}`;
  x.dataset.kind = 'finding';
  $('county-msg').hidden = true;
  let start = null;
  const wantF = wantFinding || q.get('finding'), cell = q.get('cell');
  if (wantF && store.itemById.has(wantF)) start = store.itemById.get(wantF);
  else if (cell && store.byId.has(cell) && store.itemByRef.has(store.byId.get(cell))) start = store.itemByRef.get(store.byId.get(cell));
  else start = startFinding(store);
  state.opening = start;
  setState(forced || 'ready');
  document.body.classList.remove('idle');
  const first = start.ref !== undefined ? store.values[start.ref].p : start.page || 1;
  await stage.setPage(first, false);
  if (tok !== state.openTok) return;
  stage.layout(true);
  await selectFinding(start, { animate: false });
  state.first = false;
  state.enter = !reduced && !forced;      // the first look at the sheet gets one short entrance, when it comes into view
  setFlatLabel();
  makeReplay();
  updateCounter();
}

function filterChanged() {
  const fl = state.flist;
  if (state.finding && !fl.position(state.finding.id) && fl.vis.length) selectFinding(fl.at(0));
  else updateCounter();
}

// a county with no mismatches: what the data says, and its first page lying with nothing marked
async function openEmpty(store, entry, forcedNone) {
  state.opening = null; state.sel = null; state.finding = null;
  const x = $('xpanel');
  x.dataset.kind = 'empty';
  const msg = $('county-msg');
  msg.textContent = forcedNone ? 'No mismatches found.' : emptyLine(entry);
  msg.hidden = false;
  setState(forced || 'ready');
  document.body.classList.add('idle');
  const page = store.pages.find(p => p.n === 1 && p.img) || store.pages.find(p => p.img);
  $('panel').replaceChildren(); tape.clear();
  loupe.clear();
  if (page) {
    await stage.setPage(page.n, false);
    stage.deselect();
    stage.layout(true);
    stage.setLabel(`Page ${page.n} of the scan of ${entry.name}. Nothing on it is marked: the run found no mismatch in this county.`);
  } else stage.root.classList.add('no-sheet');
  state.first = false; state.enter = false;
  setFlatLabel();
  makeReplay();
  updateCounter();
}

// a county the run did not check: the run's own sentence, and nothing to point at
function openUnchecked(entry) {
  state.store = null; state.opening = null; state.sel = null; state.finding = null; state.enter = false;
  if (state.flist) { state.flist.destroy(); state.flist = null; }
  const x = $('xpanel');
  x.dataset.kind = 'unchecked';
  const note = entry.note ? cap(entry.note) : NOT_CHECKED;
  const msg = $('county-msg');
  msg.textContent = /[.!?]$/.test(note) ? note : `${note}.`;
  msg.hidden = false;
  setState(forced || 'ready');
  state.first = false;
}

// the replay of the county's recorded run; its end puts the page back on the opening finding, drawn as on load
function makeReplay() {
  const { store } = state;
  const info = (store.fd && store.fd.run_info) || {};
  const started = state.index.started ? new Date(state.index.started) : null;
  const date = started && !isNaN(started) ? started.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }) : state.index.run;
  const o = state.opening;
  state.replay = new Replay({
    store, stage, loupe, reduced, date, onPage: () => {}, seconds: runSeconds(info), disabled: !!forced,
    els: { cap: $('rp-cap'), btn: $('replay'), speedBtn: $('speed'), hint: $('replay-hint'), card: $('panel'), findings: $('findings'), loupeEl: $('loupe'), leaderEl: $('leader') },
    headline: { set: () => {}, full: () => {} },
    restore: async animate => {
      if (o) await selectFinding(o, { animate });
      else { const pg = store.pages.find(p => p.n === 1 && p.img) || store.pages.find(p => p.img); if (pg) { await stage.setPage(pg.n, animate); stage.deselect(); } loupe.clear(); afterLoupe(); document.body.classList.add('idle'); }
    },
  });
  stage.layout(true);
}

// the first time the stage comes into view the sheet settles from flat into its tilt, the loupe rises, the sums draw
function watchReveal() {
  if (reduced || !('IntersectionObserver' in window)) return;
  const io = new IntersectionObserver(async es => {
    if (!es.some(e => e.isIntersecting) || !state.enter || !state.finding || state.finding.ref === undefined) return;
    io.disconnect();
    state.enter = false;
    const f = state.finding, settle = !stage.flat;
    if (settle) { stage.flat = true; stage.layout(true); }
    $('loupe').classList.add('rise');
    await selectValue(f, { animate: true, entrance: true, settle });
    setFlatLabel();
  }, { threshold: 0.4 });
  io.observe($('stage'));
}

// ---- the hero's two buttons
async function toExplorer() {
  const h = state.hero;
  if (h && state.key !== h.key) await openCounty(h.key, { push: true, wantFinding: h.f.id });
  scrollTo($('explore'));
  return h;
}

async function main() {
  stage.flat = q.get('flat') === '1' || reduced || innerWidth < 900;
  setFlatLabel();
  $('flat').onclick = () => { stage.setFlat(!stage.flat); setFlatLabel(); };
  $('prev').onclick = () => step(-1);
  $('next').onclick = () => step(1);
  setState('loading');
  if (forced === 'loading') {                 // stays on the loading state, for looking at it; the count is real
    try { const ix = await getJSON('data/index.json'); await getJSON(ix.counties[0].file); } catch (e) { /* the count stays where it is */ }
    return;
  }
  if (forced === 'first-run') { setState('first-run'); return; }
  try { state.index = await getJSON('data/index.json'); }
  catch (e) {
    if (e instanceof LoadError && e.missing) setState('first-run');   // nothing built yet
    else fail(e.file || 'data/index.json');
    return;
  }
  const cs = state.index.counties;
  if (!cs || !cs.length) { setState('first-run'); return; }
  if (forced === 'error') { fail(cs[0].file); return; }

  // the explaining half: from the run's totals, and one real finding from the first county that has one
  renderHeroText(state.index);
  let example = null, firstPage = null;
  try {
    for (const c of cs) {
      if (c.status === 'unchecked') continue;
      const s = await getStore(c);
      if (!firstPage) { const p = s.pages.find(p => p.img); if (p) firstPage = { img: p.img, county: c.name, n: p.n }; }
      const f = c.disagreements ? pickExample(s) : null;
      if (f) { example = { key: c.key, store: s, f }; break; }
    }
  } catch (e) { fail(e.file || cs[0].file); return; }
  state.cards = new Cards($('counties'), cs, key => { if (key !== state.key) openCounty(key, { push: true }); });
  state.hero = example ? { key: example.key, f: example.f } : null;
  setState('ready');                       // the sections take their size; the picture below measures itself
  renderHeroPic($('hero-pic'), example && example.store, example && example.f, state.index, firstPage);
  renderSteps($('steps'), example && example.store, example && example.f, firstPage);
  // the reader's sample of each county: the run's summary, else the county's own run information
  const samples = new Map();
  for (const c of cs) {
    if (c.status === 'unchecked') continue;
    let s = state.index.summary && state.index.summary[c.key] && state.index.summary[c.key].sample;
    if (!s) { try { const st = await getStore(c); s = st.fd && st.fd.run_info && st.fd.run_info.sample; } catch (e) { s = null; } }
    if (s) samples.set(c.key, s);
  }
  renderRun($('run-box'), state.index, samples);

  $('see-proof').onclick = async () => { await toExplorer(); const p = $('place'); if (p) p.focus({ preventScroll: true }); };
  $('watch').onclick = async () => {
    await toExplorer();
    const r = state.replay;
    if (r && r.available && r.state === 'idle') r.start();
  };

  const want = q.get('county');
  await openCounty(cs.some(c => c.key === want) ? want : cs[0].key);
  watchReveal();
  // a link to a county or a finding opens on the explorer
  if (q.get('county') || q.get('finding') || q.get('cell')) { state.enter = false; $('explore').scrollIntoView({ block: 'start' }); }
}

// ---- shortcuts, matched on the key's position so a keyboard layout does not matter
addEventListener('keydown', e => {
  if (!e.altKey || !e.shiftKey || e.ctrlKey || e.metaKey) return;
  if (e.code === 'KeyR') {            // back to the opening state
    e.preventDefault();
    for (const k of ['state', 'cell', 'flat', 'reset']) q.delete(k);
    location.assign(location.pathname + (q.toString() ? '?' + q : ''));
  } else if (e.code === 'KeyP') {     // the replay: start, pause, resume
    e.preventDefault();
    if (state.replay) state.replay.toggle();
  }
});
// Escape pauses a running replay (a dialog that is open takes the key for itself)
addEventListener('keydown', e => {
  if (e.key !== 'Escape' || e.altKey || e.ctrlKey || e.metaKey || $('dlg').open) return;
  if (state.replay && state.replay.state === 'running') { e.preventDefault(); state.replay.pause(); }
});

main();

:root{ color-scheme: light;
  --ff-display:"Instrument Serif","Iowan Old Style",Georgia,serif; --ff-body:"Public Sans",system-ui,sans-serif; --ff-mono:"Courier Prime",ui-monospace,monospace;
  --canvas:#FAFAF7; --surface-1:#FFFFFF; --surface-2:#F2F1EC; --desk:#ECEAE3;
  --line:#E3E1D9; --line-strong:#C9C6BC;
  --ink:#15171C; --ink-muted:#565C68;
  --accent:#15171C; --accent-ink:#FFFFFF; --focus:#1B57C4;
  --sheet:#FFFFFF; --sheet-ink:#17181A;
  --data-fails:#C4321F; --data-fails-bg:#FBE9E5; --data-holds:#1B57C4; --data-holds-bg:#E6EEFB; --warning:#8A5A00; --warning-bg:#FBF1D9;
  --r-sm:4px; --r-md:8px; --r-lg:14px; --shadow-sheet:0 30px 60px -20px rgba(21,23,28,.28), 0 8px 18px -8px rgba(21,23,28,.18); --shadow-card:0 1px 2px rgba(21,23,28,.06), 0 8px 24px -12px rgba(21,23,28,.12);
  --ease-out:cubic-bezier(.23,1,.32,1); --ease-in-out:cubic-bezier(.77,0,.175,1);
  --gutter:24px; --gap-sec:96px;
}
*{box-sizing:border-box}
[hidden]{display:none!important}
html{scroll-behavior:smooth;scroll-padding-top:68px}
body{margin:0;background:var(--canvas);color:var(--ink);font:400 17px/1.5 var(--ff-body);-webkit-text-size-adjust:100%}
:focus-visible{outline:2px solid var(--focus);outline-offset:2px}
button{font:inherit;color:inherit}
a{color:var(--ink);text-underline-offset:3px}
h1,h2,h3,h4,p,ul,ol,figure{margin:0}
ul,ol{padding:0;list-style:none}
.sr{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.wrap{width:min(1200px,calc(100% - 2 * var(--gutter)));margin-inline:auto}
.small{font-size:14px;line-height:1.45}
.skip{position:absolute;left:12px;top:-60px;z-index:100;background:var(--accent);color:var(--accent-ink);padding:10px 16px;border-radius:var(--r-md);text-decoration:none}
.skip:focus{top:8px}

/* ---- the top bar: white, 56 px, the mark and the name, four plain links */
.bar{position:sticky;top:0;z-index:50;height:56px;display:flex;align-items:center;justify-content:space-between;gap:16px;padding:0 max(var(--gutter),calc((100% - 1200px) / 2));background:var(--surface-1);border-bottom:1px solid var(--line)}
.brand{display:flex;align-items:center;gap:10px;text-decoration:none;flex:none}
.word{font:700 19px/1 var(--ff-body);letter-spacing:-.02em}
.links{display:flex;align-items:center;gap:6px}
.links a{display:inline-flex;align-items:center;min-height:40px;padding:0 12px;border-radius:var(--r-md);font-size:15px;color:var(--ink);text-decoration:none}
.links a:hover{background:var(--surface-2)}
.links a.gh{border:1px solid var(--line-strong);margin-left:6px}
.short{display:none}

/* ---- sections: 96 px apart at full width (56 under 900 px), a 1 px line between them, content at most 1200 px */
.sec{padding:calc(var(--gap-sec) / 2) 0;border-top:1px solid var(--line)}
h2{font:400 34px/1.1 var(--ff-display);letter-spacing:-.005em}
.sec-sub{margin-top:8px;color:var(--ink-muted)}

/* ---- the hero */
.hero{padding:40px 0 calc(var(--gap-sec) / 2)}
.hero-grid{display:grid;grid-template-columns:5fr 7fr;gap:48px;align-items:center}
.hero-text{min-width:0}
.eyebrow{font:600 13px/1.3 var(--ff-body);letter-spacing:.09em;text-transform:uppercase;color:var(--ink-muted)}
h1{font:400 56px/1.05 var(--ff-display);letter-spacing:-.01em;margin:14px 0 18px}
.lede{font-size:17px;max-width:34em}
.figs{display:flex;gap:28px;margin:26px 0 10px}
.figs li{min-width:0;flex:1 1 0}
.figs .n{display:block;font:700 44px/1 var(--ff-body);font-variant-numeric:tabular-nums;letter-spacing:-.02em}
.figs .l{display:block;margin-top:6px;font-size:14px;line-height:1.3;color:var(--ink-muted)}
.quiet{font-size:14px;color:var(--ink-muted)}
.actions{display:flex;flex-wrap:wrap;gap:12px;margin:24px 0 16px}
.btn{min-height:48px;padding:0 22px;border-radius:var(--r-md);border:1px solid var(--line-strong);background:var(--surface-1);font-weight:600;font-size:16px;cursor:pointer}
.btn.solid{background:var(--accent);color:var(--accent-ink);border-color:var(--accent)}
.btn:hover{border-color:var(--ink)}
.btn:active{transform:translateY(1px)}
.caveat{color:var(--ink-muted);max-width:36em}

/* the worked example: the page in depth on a pale desk, the crop of the scan lifted above it */
.hero-pic{position:relative;min-width:0;background:var(--desk);border:1px solid var(--line);border-radius:var(--r-lg);padding:22px 26px 18px;overflow:hidden}
.hp-top{position:relative}
.hp-labels{display:flex;justify-content:space-between;gap:12px;margin-bottom:26px}
.lab{margin:0;padding:5px 11px;border-radius:var(--r-md);background:var(--surface-1);font:600 15px/1.25 var(--ff-body);border:1px solid currentColor;font-variant-numeric:tabular-nums}
.lab.scan{color:var(--data-holds)}
.lab.file{color:var(--data-fails)}
.hp-crop{position:relative;z-index:2;background:var(--sheet);border:1px solid var(--line-strong);border-radius:var(--r-md);box-shadow:var(--shadow-sheet);overflow:hidden}
.hp-view{position:relative;height:176px;overflow:hidden;background:var(--sheet)}
.hp-pan{position:absolute;left:0;top:0;transform-origin:0 0}
.hp-pan img{display:block;max-width:none}
.hp-ov{position:absolute;left:0;top:0;overflow:visible}
.hp-ring{fill:none;stroke:var(--data-holds);stroke-linecap:round;stroke-linejoin:round}
.hp-lead{position:absolute;left:0;top:0;width:100%;height:100%;overflow:visible;pointer-events:none;z-index:3}
.hp-lead line{stroke-width:1.5}
.hp-lead .scan{stroke:var(--data-holds);fill:var(--data-holds)}
.hp-lead .file{stroke:var(--data-fails);fill:var(--data-fails)}
.hp-lead line.sheet{stroke:var(--ink-muted);stroke-dasharray:3 4;stroke-width:1.25}
.hp-proof{margin:16px 2px 4px;font-size:16px;line-height:1.4}
.hp-cap{margin:0 2px;font-size:13px;color:var(--ink-muted)}
.hp-desk{perspective:1500px;perspective-origin:50% 10%;margin-top:6px}
.hp-sheet{position:relative;margin:0 auto;transform-style:preserve-3d;transform:rotateX(46deg) rotateZ(-3deg);transform-origin:50% 30%}
.hp-sheet>*{position:absolute;inset:0}
.hp-sheet .face{background:var(--sheet)}
.hp-sheet .face img{display:block;width:100%;height:100%}
.face-ov{width:100%;height:100%;overflow:visible}
.face-ring{fill:none;stroke:var(--data-holds);stroke-width:7}
.hp-sheet .leaf{border-right:1px solid #a9a698;border-bottom:1px solid #a9a698}
.hp-sheet .under{background:#8f8c80;box-shadow:0 20px 34px 10px rgba(21,23,28,.34)}
.hp-plain img{display:block;width:100%;border:1px solid var(--line-strong);box-shadow:var(--shadow-sheet)}

/* ---- how it works */
.steps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;margin-top:28px}
.step{background:var(--surface-1);border:1px solid var(--line);border-radius:var(--r-lg);padding:24px;box-shadow:var(--shadow-card);min-width:0}
.step .pic{height:164px;border-radius:var(--r-md);background:var(--surface-2);overflow:hidden;margin-bottom:18px;padding:12px 14px;display:flex;flex-direction:column;justify-content:center}
.step .thumb{padding:0;display:block;position:relative}
.step .thumb img{display:block;width:100%;height:100%;object-fit:cover;object-position:50% 0}
.step h3{font:700 19px/1.25 var(--ff-body);margin-bottom:8px}
.step p{font-size:16px;line-height:1.45}
.after-steps{margin-top:24px;color:var(--ink-muted)}
.mt-title{font-size:13px;line-height:1.3;color:var(--ink-muted)}
.minitable table{width:100%;border-collapse:collapse;font-size:13px;table-layout:fixed;margin-top:6px}
.minitable th,.minitable td{padding:5px 4px;border-bottom:1px solid var(--line);font-weight:400;text-align:left;line-height:1.2}
.minitable th.num,.minitable td.num{text-align:right;font-variant-numeric:tabular-nums}
.minitable thead th{color:var(--ink-muted);font-size:13px;border-bottom:1px solid var(--line-strong);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.minitable tbody th{width:34%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.minitable thead th:first-child{width:34%}
.minitable td.bad{background:var(--data-fails-bg);color:var(--data-fails);font-weight:700;border-radius:3px}
.sums .sumline{margin:0 0 8px}
.sumline{font-size:15px;line-height:1.4;font-variant-numeric:tabular-nums}
.sumline .who{display:inline-block;min-width:3.4em;font-weight:600;color:var(--ink-muted)}
.sumline .chg{font-weight:700;padding:0 4px;border-radius:3px}
.sumline.holds .chg{background:var(--data-holds-bg);color:var(--data-holds)} .sumline.fails .chg{background:var(--data-fails-bg);color:var(--data-fails)}
.sumline.holds .tick{color:var(--data-holds);font-weight:700} .sumline.fails .tick{color:var(--data-fails);font-weight:700}

/* ---- the explorer: the county cards */
.cards{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:10px;margin:28px 0 24px}
.ccard{display:flex;flex-direction:column;gap:3px;min-height:88px;padding:13px 13px 12px;text-align:left;cursor:pointer;background:var(--surface-2);border:2px solid var(--line);border-radius:var(--r-lg)}
.ccard:hover{border-color:var(--line-strong)}
.ccard[aria-selected="true"]{background:var(--surface-1);border-color:var(--ink);box-shadow:var(--shadow-card)}
.cn{font:700 16px/1.2 var(--ff-body);color:var(--ink)}
.cw{font-size:14px;line-height:1.25;color:var(--ink-muted)}
.cbar{display:flex;gap:2px;height:4px;margin-top:auto;padding-top:0;border-radius:2px;overflow:hidden}
.cbar i{display:block;min-width:0}
.cbar .proven{background:var(--data-holds)}
.cbar .open{background:var(--warning)}
.ccard .cw+.cbar{margin-top:8px}

.x-grid{display:grid;grid-template-columns:minmax(0,7fr) minmax(0,5fr);gap:24px;align-items:start}
.x-left{min-width:0}
.stage{position:relative;height:640px;background:var(--desk);border:1px solid var(--line);border-radius:var(--r-lg);overflow:hidden}
.viewport{position:absolute;inset:0;perspective:1800px}
.viewport:focus-visible{outline-offset:-3px}
.lean{position:absolute;inset:0;transform-style:preserve-3d;will-change:transform}
.pose{position:absolute;left:0;top:0;width:0;height:0;transform-origin:0 0;transform-style:preserve-3d;will-change:transform}
.paper,.stack,.sheet,.marks{position:absolute;left:calc(var(--w) / -2);top:calc(var(--h) / -2);width:var(--w);height:var(--h)}
.paper{transform-style:preserve-3d}
.paper>.stack,.paper>.sheet{left:0;top:0}   /* inside the paper, which is already centred: otherwise the sheet sits half a sheet off the marks */
.stack{transform-style:preserve-3d}
.stack i{position:absolute;inset:0;background:#dcd9cd;border-bottom:1px solid #a9a698;border-right:1px solid #a9a698}
.stack i.under{background:#8f8c80;border:0;box-shadow:calc(var(--inv,1) * 4px) calc(var(--inv,1) * 10px) calc(var(--inv,1) * 22px) calc(var(--inv,1) * 4px) rgba(21,23,28,.34)}
.sheet{background:var(--sheet);color:var(--sheet-ink)}
.sheet img{display:block;width:100%;height:100%;user-select:none;-webkit-user-drag:none}
.far{position:absolute;left:0;right:0;top:0;height:3.5%;background:#15171C;opacity:.05;pointer-events:none}
.bands{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible}
.marks{overflow:visible;transform:translateZ(calc(var(--inv,1) * .6px))}
.marks rect{fill:transparent;cursor:pointer;stroke:none}
.marks rect:hover{stroke:var(--sheet-ink);stroke-width:calc(2 * var(--u,1))}
.bands line{stroke-width:calc(7 * var(--u,1));opacity:.3;fill:none}
.bands line.holds{stroke:var(--data-holds)} .bands line.fails{stroke:var(--data-fails)}
.bands circle,.bands path{fill:none;stroke-width:calc(3 * var(--u,1));stroke-linecap:round;stroke-linejoin:round}
.bands circle.holds,.bands path.holds{stroke:var(--data-holds)} .bands circle.fails,.bands path.fails{stroke:var(--data-fails)} .bands circle.warn,.bands path.warn{stroke:var(--warning)}
.ticks{pointer-events:none}
.ticks .tick circle{fill:none;stroke-width:2}
.ticks .tick.settled circle{stroke:var(--data-fails)} .ticks .tick.open circle{stroke:var(--warning)}
.stage.no-sheet .viewport{display:none}

.loupe{position:absolute;z-index:2;top:40px;left:50%;transform:translateX(-50%);width:min(576px,calc(100% - 48px));height:240px;background:var(--sheet);color:var(--sheet-ink);border:1px solid var(--line-strong);border-radius:6px;box-shadow:var(--shadow-sheet);overflow:hidden;transition:opacity 150ms linear}
.loupe.rise{animation:rise 300ms var(--ease-out) both}
@keyframes rise{from{transform:translate(-50%,12px);opacity:0}to{transform:translateX(-50%);opacity:1}}
.lp-view{position:absolute;inset:0;overflow:hidden}
.lp-layer{position:absolute;inset:0;opacity:0;transition:opacity 150ms linear}
.lp-layer.in{opacity:1}
.lp-layer.instant{transition:none}
.lp-pan{position:absolute;left:0;top:0;transform-origin:0 0}
.lp-pan.slide{transition:transform 350ms var(--ease-in-out)}
.lp-pan img{display:block;user-select:none;-webkit-user-drag:none}
.lp-svg{position:absolute;left:0;top:0;overflow:visible}
.lp-svg line{opacity:.26;fill:none}
.lp-svg line.holds{stroke:var(--data-holds)} .lp-svg line.fails{stroke:var(--data-fails)}
.lp-hit{fill:transparent;cursor:pointer}
.lp-hit:hover{stroke:var(--sheet-ink);stroke-width:1.5}
.lp-ring{fill:none;stroke-linecap:round;stroke-linejoin:round;pointer-events:none}
.lp-ring.holds{stroke:var(--data-holds)} .lp-ring.fails{stroke:var(--data-fails)} .lp-ring.warn{stroke:var(--warning)}
.lp-ring2{fill:none;stroke:var(--sheet-ink);stroke-dasharray:5 4;pointer-events:none}
.lp-tag{position:absolute;left:0;top:0;z-index:2;pointer-events:none;opacity:0;padding:0 8px;background:var(--surface-1);color:var(--ink);border:1px solid var(--line-strong);border-radius:var(--r-sm);font:600 14px/22px var(--ff-body);white-space:nowrap;font-variant-numeric:tabular-nums}
.lp-tag.on{opacity:1;transition:opacity 100ms linear}
.lp-tag.slide{transition:transform 350ms var(--ease-in-out),opacity 100ms linear}
.lp-tag.out{z-index:3}
.lp-tag.in-cell::after{content:"";position:absolute;right:-5px;top:10px;width:5px;height:1px;background:var(--ink)}
.lp-stem{position:absolute;z-index:1;width:1px;margin-left:-.5px;background:var(--ink);opacity:0;pointer-events:none}
.lp-stem.on{opacity:1}
.lp-cropbox{display:flex;align-items:center;justify-content:center;background:var(--sheet)}
.lp-crop{display:block;max-width:100%;max-height:100%;object-fit:contain}
.lp-tag.rep{max-width:calc(100% - 24px);overflow:hidden;text-overflow:ellipsis}
.lp-tag.rep.in-cell::after{display:none}
.leader{position:absolute;inset:0;width:100%;height:100%;z-index:3;pointer-events:none;overflow:visible}
.leader line{stroke:var(--ink);stroke-opacity:.55;stroke-width:1.5;stroke-linecap:round}

.rp-cap{position:absolute;z-index:4;top:12px;left:24px;right:24px;margin:0;font:400 14px/18px var(--ff-body);color:var(--ink);pointer-events:none}
.rp-cap:empty{display:none}
.loupe.rp-off,.leader.rp-off{opacity:0;pointer-events:none}
.lp-tag.rp-off{opacity:0!important}
.rp{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible}
.rp .wash{fill:var(--data-holds);fill-opacity:.12;transform-box:fill-box;transform-origin:0 50%}
.rp .wash.sweep{animation:sweep 180ms linear both}
.rp .wash.fade{animation:fade 150ms linear both}
.rp .frame{fill:none;stroke:var(--sheet-ink);stroke-width:calc(2 * var(--u,1));stroke-dasharray:calc(8 * var(--u,1)) calc(5 * var(--u,1))}
.rp .sum{fill:none;stroke-width:calc(7 * var(--u,1));opacity:.3}
.rp .sum.fails{stroke:var(--data-fails)} .rp .sum.holds{stroke:var(--data-holds)}
body.replaying .ticks{display:none}
body.replaying.rp-ticks .ticks{display:inline}
.ticks .tick.pop{animation:tickin 220ms var(--ease-out) both}
@keyframes sweep{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@keyframes tickin{from{opacity:0}to{opacity:1}}
@keyframes fade{from{opacity:0}to{opacity:1}}
body.replaying .panel,body.replaying .findings{opacity:.55;transition:opacity 150ms linear}

/* partial: no page image, so the block's own image is shown flat where the sheet would be */
.stage.partial .viewport{display:none}
.flatblock{display:none}
.stage.partial .flatblock{display:block;position:absolute;z-index:1;left:24px;right:24px;top:292px;bottom:24px;overflow:hidden;background:var(--sheet);color:var(--sheet-ink);border:1px solid var(--line-strong)}
.fb-pan{position:absolute;left:0;top:0;transform-origin:0 0}
.fb-pan img{display:block}
.fb-svg{position:absolute;left:0;top:0;overflow:visible}
.fb-svg line{opacity:.26;fill:none} .fb-svg line.holds{stroke:var(--data-holds)} .fb-svg line.fails{stroke:var(--data-fails)}
.fb-hit{fill:transparent;cursor:pointer}
.fb-ring{fill:none;stroke-linecap:round;stroke-linejoin:round;pointer-events:none}
.fb-ring.holds{stroke:var(--data-holds)} .fb-ring.fails{stroke:var(--data-fails)}

/* the controls under the stage */
.controls{display:flex;flex-wrap:wrap;align-items:center;gap:10px 14px;margin-top:14px}
.c-step,.c-replay{display:flex;align-items:center;flex-wrap:wrap;gap:10px}
.c-replay{margin-left:auto}
.controls button{min-height:40px;padding:0 16px;border:1px solid var(--line-strong);border-radius:var(--r-md);background:var(--surface-1);cursor:pointer}
.controls button:hover:not(:disabled){border-color:var(--ink)}
.controls button:disabled{color:var(--ink-muted);background:var(--surface-2);cursor:default}
.controls .replay-btn{background:var(--accent);color:var(--accent-ink);border-color:var(--accent);font-weight:600}
.controls .replay-btn:disabled{background:var(--surface-2);color:var(--ink-muted);border-color:var(--line-strong)}
.counter{min-width:5.2em;font-size:15px;color:var(--ink-muted);font-variant-numeric:tabular-nums}
.hint{font-size:13px;color:var(--ink-muted)}
#speed{min-width:6.5em}

/* the panel: the finding in plain words */
.panel{background:var(--surface-1);border:1px solid var(--line);border-radius:var(--r-lg);padding:24px;box-shadow:var(--shadow-card);min-width:0}
.place{font:700 22px/1.2 var(--ff-body);letter-spacing:-.01em}
.place:focus-visible{outline-offset:4px}
.printed{margin:4px 0 18px;font-size:14px;color:var(--ink-muted)}
.two-values{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.two-values .one{border-radius:var(--r-md);padding:12px 14px;background:var(--surface-2);min-width:0}
.two-values .lab{display:block;margin:0 0 2px;padding:0;border:0;background:none;font:600 13px/1.3 var(--ff-body);color:var(--ink-muted)}
.two-values .fig{display:block;font:700 40px/1.1 var(--ff-body);font-variant-numeric:tabular-nums;letter-spacing:-.02em;overflow-wrap:anywhere}
.panel.proven .two-values .one.file{background:var(--data-fails-bg)} .panel.proven .two-values .file .fig{color:var(--data-fails)}
.panel.proven .two-values .one.scan{background:var(--data-holds-bg)} .panel.proven .two-values .scan .fig{color:var(--data-holds)}
.sentence{margin:16px 0 8px}
.status{margin:0 0 16px;font-weight:600}
.status .sg{display:inline-block;min-width:1.3ch;margin-right:6px}
.status.ok{color:var(--data-holds)} .status.open{color:var(--warning)}
.why{background:var(--surface-2);border-radius:var(--r-md);padding:14px 16px;margin-bottom:12px}
.why h4{font:700 13px/1.2 var(--ff-body);letter-spacing:.08em;text-transform:uppercase;color:var(--ink-muted);margin-bottom:8px}
.why .sumline{margin:4px 0}
.why .sumline .who{display:inline;min-width:0;font-weight:600;color:var(--ink-muted);margin-right:2px}
.why .printed-total,.why .why-not{margin-top:6px;font-size:15px}
.why .printed-total{color:var(--ink-muted)}
.every{margin:0 0 12px}
.every summary{display:flex;align-items:center;min-height:44px;cursor:pointer;font-weight:600;color:var(--ink)}
.person{font-size:14px;color:var(--ink-muted)}
.btns{display:flex;flex-wrap:wrap;gap:10px;margin-top:14px}
.btns button,.dlg-close{min-height:40px;padding:0 16px;background:var(--surface-1);color:var(--ink);border:1px solid var(--line-strong);border-radius:var(--r-md);cursor:pointer}
.btns button:hover,.dlg-close:hover{border-color:var(--ink)}
/* the report layout's four figures */
.two-values.rep{display:block}
.rv{display:grid;grid-template-columns:84px repeat(4,minmax(0,1fr));gap:0 8px;align-items:baseline}
.rv.head{margin-bottom:2px}
.rv .colh{font-size:13px;line-height:1.3;color:var(--ink-muted);text-align:right;white-space:nowrap;overflow:hidden}
.two-values.rep .one{display:grid;padding:8px 12px;margin-top:6px}
.two-values.rep .one .lab{font-size:13px;white-space:nowrap}
.rv .fg{font:400 20px/1.25 var(--ff-body);font-variant-numeric:tabular-nums;text-align:right;color:var(--ink-muted)}
.rv .fg.d{font-weight:700;color:var(--ink);font-size:24px}
.panel.proven .two-values.rep .one.file .fg.d{color:var(--data-fails)} .panel.proven .two-values.rep .one.scan .fg.d{color:var(--data-holds)}

/* the full tape: Courier Prime, here only */
.tape{position:relative;background:var(--sheet);color:var(--sheet-ink);padding:10px 14px 16px;font:400 13px/16px var(--ff-mono);min-height:48px}
.tapewrap{filter:drop-shadow(0 2px 6px rgba(21,23,28,.18));margin-bottom:6px}
.tape h3{margin:0 0 2px;font:600 13px/16px var(--ff-body);color:#3f4450}
.tape .ln{display:flex;justify-content:space-between;gap:12px;white-space:pre}
.tape .ln span:last-child{text-align:right;font-variant-numeric:tabular-nums}
.tape .ln.rule{border-top:1.5px solid var(--sheet-ink);margin-top:2px;padding-top:2px}
.tape .ln.more{color:#3f4450}
.tape .res{margin-top:2px;padding:0 8px;font-weight:700;display:inline-block}
.tape .res.holds{background:var(--data-holds-bg);color:var(--data-holds)} .tape .res.fails{background:var(--data-fails-bg);color:var(--data-fails)}
.tape .empty{margin:0;color:#3f4450;font:400 14px var(--ff-body)}
.tape.two{display:block}
.tape .sum.two h3{margin:0 0 2px}
.tape.two .sum+.sum{margin-top:8px;padding-top:6px;border-top:1px dashed var(--line-strong)}
.tape .pair{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:0 18px}
.tape .pair.heads h4{margin:0;font:600 13px/16px var(--ff-body);color:#3f4450}
.tape .pair.rule{border-top:1.5px solid var(--sheet-ink);margin-top:2px;padding-top:2px}
.tape .pair.rule .ln{border:0;margin:0;padding:0}
.tape .ln.diff{background:var(--data-fails-bg);box-shadow:inset 3px 0 0 var(--data-fails);padding-left:5px}
.tape .pair>.ln:last-child.diff{background:var(--data-holds-bg);box-shadow:inset 3px 0 0 var(--data-holds)}
.tape .res2{margin-top:2px}
.tape .res2 .res{margin-top:0;display:block;white-space:nowrap}
.tape .others{margin-top:14px;padding-top:8px;border-top:1px dashed var(--line-strong);color:#3f4450;font-size:13px}
.tape .others>h3{margin:0 0 4px}
.tape .sum.quiet{margin-top:6px;opacity:.95}
.tape.rep .pair .ln>span:first-child{position:relative;min-width:0;overflow:hidden;text-overflow:ellipsis}
.tape.rep .pair .ln>span:last-child{flex:none}

/* the list of the county's findings */
.findings{margin-top:32px}
.f-head{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-bottom:12px}
.f-head h3{font:700 20px/1.2 var(--ff-body)}
.seg{display:inline-flex;border:1px solid var(--line-strong);border-radius:var(--r-md);overflow:hidden;background:var(--surface-1)}
.segb{min-height:40px;padding:0 16px;background:var(--surface-1);border:0;border-left:1px solid var(--line);cursor:pointer;font-size:15px}
.segb:first-child{border-left:0}
.segb[aria-pressed="true"]{background:var(--accent);color:var(--accent-ink);font-weight:600}
.segb:focus-visible{outline-offset:-3px}
.segn{font-variant-numeric:tabular-nums;opacity:.85}
.showing{margin:0 0 8px;font-size:14px;color:var(--ink-muted)}
.showing:empty{display:none}
.flist-wrap{max-height:440px;overflow:auto;border:1px solid var(--line);border-radius:var(--r-lg);background:var(--surface-1)}
.flist{margin:0}
.flist.virtual{position:relative}
.flist:focus-visible{outline:2px solid var(--focus);outline-offset:-2px}
.flist li{font-size:15px;line-height:1.3}
.flist li.grp{display:grid;grid-template-columns:auto auto minmax(0,1fr) auto;gap:0 10px;align-items:baseline;padding:10px 16px 6px;background:var(--surface-2);border-bottom:1px solid var(--line)}
.flist li.grp .kg{font-weight:700;min-width:1.2ch;text-align:center}
.flist li.grp .kw{font-weight:700}
.flist li.grp .rl{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.flist li.grp .pc{color:var(--ink-muted);font-size:14px;white-space:nowrap}
.flist li.fnd{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(8.5em,auto);gap:0 16px;align-items:center;padding:6px 16px;border-bottom:1px solid var(--line);cursor:pointer;min-height:40px}
.flist li.fnd:hover{background:var(--surface-2)}
.flist li.fnd[aria-selected="true"]{background:var(--surface-2);box-shadow:inset 3px 0 0 var(--ink)}
.flist li.fnd.cur{outline:2px solid var(--focus);outline-offset:-2px}
.flist:not(:focus-visible) li.cur{outline:0}
.flist .vs{font-variant-numeric:tabular-nums;white-space:nowrap}
.flist .ar{margin:0 6px;color:var(--ink-muted)}
.flist .sv{font-weight:700}
.flist .st{font-size:14px;white-space:nowrap}
.flist .st .sg{display:inline-block;min-width:1.3ch;margin-right:4px}
.flist .st.ok{color:var(--data-holds)} .flist .st.open{color:var(--warning)}
.flist.virtual li{overflow:hidden}
.flist.virtual li.fnd .wh{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

/* a county with nothing found, a county that was not checked, a county that cannot be loaded */
.county-msg{max-width:36em;margin:36px auto 28px;text-align:center;font-size:21px;line-height:1.4}
.xpanel[data-kind="empty"] .x-grid{grid-template-columns:minmax(0,760px);justify-content:center}
.xpanel[data-kind="empty"] .panel,.xpanel[data-kind="empty"] .c-step,.xpanel[data-kind="empty"] #flat,.xpanel[data-kind="empty"] .findings{display:none}
.xpanel[data-kind="empty"] .stage{height:420px}
.xpanel[data-kind="empty"] .c-replay{margin-left:0}
.xpanel[data-kind="unchecked"] .x-grid,.xpanel[data-kind="unchecked"] .findings,.xpanel[data-kind="error"] .x-grid,.xpanel[data-kind="error"] .findings{display:none}
.xpanel[data-kind="unchecked"] .county-msg{margin:48px auto}
.notice{max-width:520px;margin:0 auto;background:var(--data-fails-bg);color:var(--ink);border:1px solid var(--data-fails);border-radius:var(--r-md);padding:16px 20px;font-size:16px}
.notice.in-stage{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);z-index:4;background:var(--surface-1)}
.notice.local{margin:32px auto}

/* ---- the run */
.run-body{margin-top:20px;max-width:900px}
.run-line{font:400 22px/1.4 var(--ff-body);margin-bottom:28px}
.bars h3{font:700 17px/1.3 var(--ff-body);margin-bottom:10px}
.bar-row{display:grid;grid-template-columns:190px minmax(0,1fr) 190px;gap:16px;align-items:center;margin:10px 0}
.bl{font-size:16px}
.track{height:16px;border-radius:8px;background:var(--data-fails-bg);overflow:hidden}
.track i{display:block;height:100%;background:var(--data-holds)}
.bv{font-size:16px;color:var(--ink-muted);font-variant-numeric:tabular-nums}
.bv strong{font:700 26px/1 var(--ff-body);color:var(--ink)}
.reader{margin-top:28px;max-width:44em}
.evid-h{font:700 17px/1.3 var(--ff-body);margin:28px 0 8px}
.evid{display:flex;flex-wrap:wrap;gap:6px 28px}
.evid a{display:inline-flex;align-items:center;min-height:40px}
.limits{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px 48px;margin-top:24px}
.limits li{padding-top:14px;border-top:2px solid var(--line-strong);font-size:18px;line-height:1.4}

.foot{border-top:1px solid var(--line);padding:32px 0 40px;color:var(--ink-muted);font-size:14px}
.foot a{color:var(--ink)}

/* ---- the dialogs */
.dlg{background:var(--surface-1);color:var(--ink);border:1px solid var(--line-strong);border-radius:var(--r-lg);padding:0;width:min(760px,calc(100vw - 32px));max-height:calc(100vh - 48px);box-shadow:var(--shadow-sheet)}
.dlg::backdrop{background:rgba(21,23,28,.45)}
.dlg[open]{display:flex;flex-direction:column}
.dlg-head{display:flex;gap:12px;align-items:center;justify-content:space-between;padding:14px 20px;border-bottom:1px solid var(--line)}
.dlg-title{font:700 17px/1.3 var(--ff-body);overflow-wrap:anywhere}
.dlg-body{padding:16px 20px 20px;overflow:auto;min-height:0}
.dlg-fig{margin:0 0 12px;background:var(--sheet);border:1px solid var(--line);padding:6px}
.dlg-fig img{display:block;max-width:100%;height:auto}
.dlg-note{margin:0 0 12px;font-size:15px;color:var(--ink-muted)}
.dlg-sum{margin:0 0 12px}
.dlg-sum h3{margin:0 0 2px;font:700 15px/1.3 var(--ff-body)}
.dlg-sum ul{margin:0;padding-left:20px;list-style:disc;font-size:15px;line-height:1.45}
.dlg-pre{margin:0;padding:12px;background:var(--surface-2);border:1px solid var(--line);border-radius:var(--r-md);font:400 13px/1.45 var(--ff-mono);overflow:auto;max-height:60vh;white-space:pre-wrap;overflow-wrap:anywhere}

/* ---- states: body[data-state] = loading | error | first-run | ready (empty and partial change the explorer only) */
.hero-state{display:none;position:relative;min-height:62vh;background:var(--desk);border:1px solid var(--line);border-radius:var(--r-lg);overflow:hidden}
body[data-state="loading"] .hero-state,body[data-state="error"] .hero-state,body[data-state="first-run"] .hero-state{display:block}
body[data-state="loading"] .hero-grid,body[data-state="error"] .hero-grid,body[data-state="first-run"] .hero-grid,
body[data-state="loading"] .sec,body[data-state="error"] .sec,body[data-state="first-run"] .sec{display:none}
.ghost{position:absolute;inset:0;perspective:1800px;overflow:hidden;pointer-events:none}
body[data-state="error"] .ghost,body[data-state="first-run"] .ghost{display:none}
.ghost-sheet{position:absolute;left:50%;top:50%;width:min(62%,560px);aspect-ratio:1600/971;background:var(--sheet);box-shadow:var(--shadow-sheet);transform:translate(-50%,-50%) rotateX(34deg) rotateZ(-3deg);overflow:hidden}
.scanline{position:absolute;left:0;right:0;top:0;height:3px;background:var(--data-holds);animation:scan 1.6s linear infinite}
@keyframes scan{from{top:-3px}to{top:100%}}
.statebox{position:absolute;left:24px;right:24px;bottom:40px;margin:0;font:600 16px/1.4 var(--ff-body);text-align:center;font-variant-numeric:tabular-nums}
body[data-state="first-run"] .statebox{top:50%;bottom:auto;transform:translateY(-50%);max-width:480px;margin:0 auto}
.hero-state .notice{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(520px,calc(100% - 48px))}

/* a short window (also a page zoomed to 160 percent): the loupe gets shorter so the sheet keeps room */
@media (min-width:900px) and (max-height:720px){
  .stage{height:560px}
  .loupe{top:36px;height:170px}
  .stage.partial .flatblock{top:228px}
}
@media (max-width:1100px){
  .cards{display:flex;overflow-x:auto;padding-bottom:8px;scrollbar-width:thin}
  .ccard{flex:0 0 150px}
  h1{font-size:48px}
  .figs{gap:20px}
  .figs .n{font-size:40px}
}
@media (max-width:899px){
  :root{--gutter:16px;--gap-sec:56px}
  html{scroll-padding-top:64px}
  h1{font-size:36px;margin:10px 0 14px}
  .hero{padding-top:24px}
  .hero-grid{display:flex;flex-direction:column;gap:20px;align-items:stretch}
  .hero-text{display:contents}
  .hero-pic{order:6;padding:16px 14px 12px}
  .actions{order:7;margin:4px 0 0}
  .caveat{order:8}
  .figs{margin:18px 0 6px;gap:12px}
  .figs .n{font-size:44px}
  .figs .l{font-size:14px}
  .hero-grid>.hero-text>*{margin-top:0}
  .lede,.figs,.quiet{margin-top:0}
  .hp-view{height:132px}
  .hp-labels{margin-bottom:22px}
  .lab{font-size:14px;padding:4px 8px}
  .steps,.limits{grid-template-columns:minmax(0,1fr)}
  .x-grid{grid-template-columns:minmax(0,1fr)}
  .stage{height:clamp(400px,58vh,520px)}
  .loupe{top:36px;width:calc(100% - 24px);height:clamp(104px,18vh,150px)}
  .rp-cap{top:8px;left:12px;right:12px;font-size:13px;line-height:15px}
  .controls button{min-height:44px}
  .c-replay{margin-left:0;width:100%}
  .panel{padding:20px 16px}
  .bar-row{grid-template-columns:minmax(0,1fr);gap:4px}
  .bv strong{font-size:24px}
  .btns button,.dlg-close,.segb{min-height:44px}
  .stage.partial .flatblock{left:12px;right:12px;top:calc(36px + clamp(104px,18vh,150px) + 10px);bottom:12px}
  .xpanel[data-kind="empty"] .stage{height:clamp(260px,40vh,360px)}
  .county-msg{font-size:19px}
  .flist li.fnd{grid-template-columns:minmax(0,1fr) auto;min-height:44px;row-gap:2px}
  .flist li.fnd .st{grid-column:1/-1}
  .flist li.grp{grid-template-columns:auto auto minmax(0,1fr)}
  .flist li.grp .pc{grid-column:2/-1;white-space:normal}
  .rv{grid-template-columns:70px repeat(4,minmax(0,1fr));gap:0 4px}
  .rv .fg{font-size:17px} .rv .fg.d{font-size:20px}
  .rv .colh{font-size:13px}
  .tape .pair .ln{font-size:13px}
  .lp-tag.rep{font-size:13px;letter-spacing:-.02em}
}
@media (max-width:640px){
  .long{display:none}
  .short{display:inline}
  .links{gap:0}
  .links a{padding:0 9px;font-size:14px}
  .links a.gh{margin-left:2px}
  .word{font-size:17px}
}
@media (max-width:379px){
  .word{display:none}
  .figs .n{font-size:38px}
}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  .lp-pan.slide,.lp-tag.slide,.lp-tag.on{transition:none}
  .lp-layer{transition:opacity 150ms linear}
  .loupe.rise{animation:none}
  .scanline{animation:none;top:50%}
  .rp .wash.sweep{animation:fade 150ms linear both}
  .ticks .tick.pop{animation:fade 150ms linear both}
  .loupe{transition:opacity 150ms linear}
  .btn:active{transform:none}
}

